```sql
alter table public.profiles enable row level security;

-- R1: Anyone can read every profile
create policy "Public profiles are viewable by everyone" on public.profiles
  for select using (true);

-- R2: Signed-in users can create a profile only for themselves
create policy "Users can create their own profile" on public.profiles
  for insert with check (auth.uid() = id);

-- R3: Users can edit only their own profile
create policy "Users can update own profile" on public.profiles
  for update using (auth.uid() = id)
  with check (auth.uid() = id);

-- R4: Profiles cannot be deleted (enforced for all roles including service_role via deny)
-- We use a deny policy on delete that blocks everyone; service_role bypasses RLS so
-- we rely on the application not issuing deletes, but the policy documents the intent.
create policy "Profiles are non-deletable" on public.profiles
  for delete using (false);

-- R5: Anonymous visitors cannot create or change profiles is covered by R2/R3
-- (insert requires auth.uid(), update/delete use auth.uid() checks).

-- R6: Server-side code using the service role keeps full access
-- No extra policy needed; service_role bypasses RLS by default.

-- Grant usage of auth.uid() to anon if needed for the select policy above;
-- anon can already read due to the "using (true)" policy, but we ensure the function
-- is available should any policy reference it.
grant usage on function auth.uid() to anon;
