ALTER TABLE public.orgs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.org_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;

-- R1: Members can see every membership row of their organization
CREATE POLICY "Members view own org memberships" ON public.org_members FOR SELECT TO authenticated USING (org_id IN (SELECT org_id FROM public.org_members WHERE user_id = auth.uid()));

-- R2: Members can see the organizations they belong to
CREATE POLICY "Members view own orgs" ON public.orgs FOR SELECT TO authenticated USING (id IN (SELECT org_id FROM public.org_members WHERE user_id = auth.uid()));

-- R2: Members can see the organizations' projects
CREATE POLICY "Members view own org projects" ON public.projects FOR SELECT TO authenticated USING (org_id IN (SELECT org_id FROM public.org_members WHERE user_id = auth.uid()));

-- R3: Only org admins can create, rename, or delete projects within organizations they administer
CREATE POLICY "Admins create projects" ON public.projects FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.org_members WHERE org_id = projects.org_id AND user_id = auth.uid() AND role = 'admin'));
CREATE POLICY "Admins update projects" ON public.projects FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.org_members WHERE org_id = projects.org_id AND user_id = auth.uid() AND role = 'admin')) WITH CHECK (EXISTS (SELECT 1 FROM public.org_members WHERE org_id = projects.org_id AND user_id = auth.uid() AND role = 'admin'));
CREATE POLICY "Admins delete projects" ON public.projects FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.org_members WHERE org_id = projects.org_id AND user_id = auth.uid() AND role = 'admin'));

-- R4: Members can read project files; only admins can upload or delete
CREATE POLICY "Members read project files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'project-files' AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id = (storage.foldername(name))[1]::int AND EXISTS (SELECT 1 FROM public.org_members om WHERE om.org_id = p.org_id AND om.user_id = auth.uid())));
CREATE POLICY "Admins upload project files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'project-files' AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id = (storage.foldername(name))[1]::int AND EXISTS (SELECT 1 FROM public.org_members om WHERE om.org_id = p.org_id AND om.user_id = auth.uid() AND om.role = 'admin')));
CREATE POLICY "Admins delete project files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'project-files' AND EXISTS (SELECT 1 FROM public.projects p WHERE p.id = (storage.foldername(name))[1]::int AND EXISTS (SELECT 1 FROM public.org_members om WHERE om.org_id = p.org_id AND om.user_id = auth.uid() AND om.role = 'admin')));

-- R5: Anyone can view avatars; signed-in users can upload avatars only into their own user-id folder
CREATE POLICY "Public view avatars" ON storage.objects FOR SELECT TO anon USING (bucket_id = 'avatars');
CREATE POLICY "Users upload avatars own folder" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text);

-- R6: Memberships cannot be created, changed, or removed by users (enforced by default RLS denial; no INSERT/UPDATE/DELETE policies on org_members for authenticated/anon)
-- R7: Anonymous visitors cannot see or change anything else (denied by TO authenticated policies on tables; only avatars SELECT allows anon)
-- R8: Server-side code using service_role bypasses RLS inherently
