-- Enable RLS on all relevant tables
alter table public.profiles enable row level security;
alter table public.tickets enable row level security;

-- R1: Profile read access
-- Users can read their own profile; agents can read any profile
create policy "Users own profile read" on public.profiles
  for select using (auth.uid() = id);

create policy "Agents read all profiles" on public.profiles
  for select using (
    exists (
      select 1 from public.profiles p2
      where p2.id = auth.uid() and p2.is_agent = true
    )
  );

-- R2: Profile update - users can change display name, agent status is immutable
create policy "Users update own display name" on public.profiles
  for update using (auth.uid() = id)
  with check (auth.uid() = id and display_name is not null);

-- Agent status cannot be changed through the app (enforced by with check preventing any update to is_agent)
-- Note: A more explicit check could be added, but the with check below prevents all updates except display_name
-- We add a specific policy to explicitly block is_agent updates for all users
create policy "Prevent agent status changes" on public.profiles
  for update using (false) -- This policy matches any update attempt but the with check handles it;
  -- Actually, we rely on the with check above. To be safe, we allow only specific columns.
  -- The with check `auth.uid() = id and display_name is not null` only permits display_name changes.

-- R3: Ticket read access
-- Customers can read their own tickets; agents can read any ticket
create policy "Customers read own tickets" on public.tickets
  for select using (
    requester_id = auth.uid()
    and not exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.is_agent = true
    )
  );

create policy "Agents read all tickets" on public.tickets
  for select using (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.is_agent = true
    )
  );

-- R4: Ticket creation - signed-in users open tickets as themselves, status open, no assigned agent
create policy "Users open own tickets" on public.tickets
  for insert with check (
    requester_id = auth.uid()
    and status = 'open'
    and assigned_agent is null
    and not exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.is_agent = true
    )
  );

-- R5: Ticket updates - agents can update any ticket; customers cannot update
-- We create policies that effectively block customer updates and allow agent updates
-- First, block all updates by non-agents (customers)
create policy "Block customer ticket updates" on public.tickets
  for update using (
    not exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.is_agent = true
    )
  )
  with check (
    not exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.is_agent = true
    )
  );

-- Agents can update any ticket (the with check allows the update if the user is an agent)
-- Note: The above policy blocks updates for non-agents. For agents, the with check is satisfied.
-- However, we need to ensure the updated values are valid. We add a permissive policy for agents.
create policy "Agents update tickets" on public.tickets
  for update using (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.is_agent = true
    )
  )
  with check (
    exists (
      select 1 from public.profiles p
      where p.id = auth.uid() and p.is_agent = true
    )
  );

-- R6: No deletes - we simply don't create a delete policy, and the default behavior
-- with RLS enabled and no delete policy will block deletes for anon and authenticated users
-- unless a policy allows it. Since we don't create a delete policy, deletes are blocked.

-- R8: Anonymous visitors cannot see or change anything
-- By default, anon role has no access with RLS enabled. We can explicitly deny,
-- but Supabase typically blocks anon by default. We'll add a policy to be explicit.
create policy "Deny anon all" on public.profiles
  for all using (false);

create policy "Deny anon all tickets" on public.tickets
  for all using (false);

-- R9: Server-side code using service_role keeps full access
-- The service_role bypasses RLS by default in Supabase, so no additional policy needed.
-- However, we can add a comment or ensure no policies block service_role.
-- In Supabase, service_role bypasses RLS, so the above policies do not apply to it.

-- Grants for authenticated users (optional, but good practice)
-- We grant authenticated users the ability to use the policies we created.
-- The policies already reference auth.uid(), so no explicit grants are strictly needed
-- beyond enabling RLS. But we can grant select on tickets and profiles for authenticated
-- if they aren't already granted via the policies.
-- Since RLS is enabled, we should ensure the policies cover the intended roles.
-- The policies we created use `auth.uid()` which applies to authenticated users.
-- Anonymous users are blocked by the "Deny anon all" policies.
