-- Enable RLS on posts and comments
alter table public.posts enable row level security;
alter table public.comments enable row level security;

-- Helper function: check if a post is live (published and not unpublished)
create function public.is_post_live(pid uuid) returns boolean language sql immutable as
$$ select published_at IS NOT NULL 
         and published_at <= now() 
         and (unpublish_at IS NULL OR unpublish_at > now()); $$;

-- Posts RLS policies
-- R1: Anyone (including anon) can read live posts
create policy "posts_anon_live_read" on public.posts
for select using (public.is_post_live(id));

-- R2: Authors can read all of their own posts, live or not
create policy "posts_author_own_read" on public.posts
for select using (author_id = auth.uid());

-- R3: Signed-in users can write posts only as themselves
create policy "posts_author_insert" on public.posts
for insert with check (author_id = auth.uid());

-- R3: Authors can update their own posts
create policy "posts_author_update" on public.posts
for update using (author_id = auth.uid());

-- R3: Authors can delete their own posts
create policy "posts_author_delete" on public.posts
for delete using (author_id = auth.uid());

-- Comments RLS policies
-- R4: Comment visible to exactly the people who can read the post it belongs to
-- R5: Signed-in users can comment as themselves on posts they can read
-- R6: Comment authors can delete own, post authors can delete any on their posts; nobody can edit

-- Comments SELECT: visible if post is live or user is the post author
create policy "comments_live_or_author_read" on public.comments
