returns boolean language sql strict as $$
  select case
    when exists (
      select 1 from public.delegations
      where grantor_id = is_valid_delegation.grantor_id
        and delegate_id = is_valid_delegation.delegate_id
        and (expires_at is null or expires_at > now())
