-- Enable Row Level Security on all relevant tables
alter table public.conversations enable row level security;
alter table public.participants enable row level security;
alter table public.messages enable row level security;
alter table public.blocks enable row level security;

-- Helper function to check if user is blocked in a conversation context
create or replace function public.is_blocked_by_participant(blocker_id uuid, blocked_id uuid, conversation_id bigint)
returns boolean language sql stable as $$
  select exists (
    select 1 from public.participants p1
    join public.participants p2 on p1.conversation_id = p2.conversation_id
    where p1.user_id = blocker_id
      and p2.user_id = blocked_id
      and p1.conversation_id = conversation_id
  );
$$;

-- R1: Users can see conversations they participate in and all participants of those conversations
create policy "users see their conversations and participants" on public.conversations
  for select using (
    exists (select 1 from public.participants where conversation_id = id and user_id = auth.uid())
  );

create policy "users see participants of their conversations" on public.participants
  for select using (
    exists (select 1 from public.participants p2 where p2.conversation_id = conversation_id)
  );

-- R2: Users can read messages in conversations they participate in
create policy "users read messages in their conversations" on public.messages
  for select using (
    exists (select 1 from public.participants where conversation_id = conversation_id and user_id = auth.uid())
  );

-- R3: Users can send messages unless blocked by another participant
create policy "users send messages if not blocked" on public.messages
  for insert with check (
    -- Sender must be a participant
    exists (select 1 from public.participants where conversation_id = conversation_id and user_id = auth.uid())
    and not public.is_blocked_by_participant(auth.uid(), sender_id, conversation_id)
  );

-- R4: Senders can edit/delete their own messages
create policy "senders edit own messages" on public.messages
  for update using (sender_id = auth.uid());

create policy "senders delete own messages" on public.messages
  for delete using (sender_id = auth.uid());

-- R5: Users can manage their own blocks; cannot see who blocked them
create policy "users manage own blocks" on public.blocks
  for all using (blocker_id = auth.uid())
  with check (blocker_id = auth.uid());

-- R6: Conversations and participants cannot be created or changed (insert/update/delete blocked)
-- Prevent insert into conversations
create policy "no insert conversations" on public.conversations
  for insert with check (false);

-- Prevent update conversations
create policy "no update conversations" on public.conversations
  for update using (false);

-- Prevent delete conversations
create policy "no delete conversations" on public.conversations
  for delete using (false);

-- Prevent insert participants
create policy "no insert participants" on public.participants
  for insert with check (false);

-- Prevent update participants
create policy "no update participants" on public.participants
  for update using (false);

-- Prevent delete participants
create policy "no delete participants" on public.participants
  for delete using (false);

-- R7: Anonymous visitors cannot see or change anything
-- Deny all anon access by making policies restrictive (already covered by above, but explicit)
-- No additional policy needed as anon access is denied by default when RLS is enabled and no anon policy exists, 
-- but to be safe we ensure anon is denied:
revoke all on public.conversations from anon;
revoke all on public.participants from anon;
revoke all on public.messages from anon;
revoke all on public.blocks from anon;

-- R8: Service role keeps full access
grant all on public.conversations to service_role;
grant all on public.participants to service_role;
grant all on public.messages to service_role;
grant all on public.blocks to service_role;
grant usage on schema public to service_role;
