alter table public.wallets enable row level security;
alter table public.transfers enable row level security;

create policy "users_read_own_wallet" on public.wallets
for select using (user_id = auth.uid());

create policy "users_read_own_transfers" on public.transfers
for select using (from_user = auth.uid() or to_user = auth.uid());

create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
as $$
declare
  v_sender uuid;
  v_sender_balance integer;
  v_recipient_balance integer;
  v_new_transfer bigint;
begin
  v_sender := auth.uid();
  if v_sender is null then
    raise exception 'Caller must be signed in';
  end if;

  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  select balance into v_sender_balance from public.wallets where user_id = v_sender;
  if v_sender_balance is null then
    raise exception 'Sender has no wallet';
  end if;
  if v_sender_balance < p_amount then
    raise exception 'Insufficient points';
  end if;

  select balance into v_recipient_balance from public.wallets where user_id = p_to;
  if v_recipient_balance is null then
    raise exception 'Recipient has no wallet';
  end if;

  if v_sender = p_to then
    raise exception 'Caller cannot send points to themselves';
  end if;

  update public.wallets set balance = balance - p_amount where user_id = v_sender;
  update public.wallets set balance = balance + p_amount where user_id = p_to;

  insert public.transfers (from_user, to_user, amount)
  values (v_sender, p_to, p_amount)
  returning id into v_new_transfer;

  return v_new_transfer;
end;
$$;
