alter table public.wallets enable row level security;
alter table public.transfers enable row level security;

create policy wallets_select_own on public.wallets for select using (auth.uid() = user_id);

create policy transfers_select_own on public.transfers for select using (auth.uid() = from_user or auth.uid() = to_user);

create function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
as $$
declare
  from_user uuid := auth.uid();
  new_id bigint;
begin
  set local row_security = off;
  if from_user is null then
    raise exception 'caller not signed in';
  end if;
  if p_amount <= 0 then
    raise exception 'amount must be positive';
  end if;
  if not exists (select 1 from public.wallets where user_id = from_user) then
    raise exception 'caller has no wallet';
  end if;
  if not exists (select 1 from public.wallets where user_id = p_to) then
    raise exception 'recipient has no wallet';
  end if;
  if from_user = p_to then
    raise exception 'caller and recipient must be different';
  end if;
  if (select balance from public.wallets where user_id = from_user) < p_amount then
    raise exception 'insufficient points';
  end if;
  update public.wallets set balance = balance - p_amount where user_id = from_user;
  update public.wallets set balance = balance + p_amount where user_id = p_to;
  insert into public.transfers (from_user, to_user, amount, created_at)
  values (from_user, p_to, p_amount, now())
  returning id into new_id;
  return new_id;
end;
$$;

