```sql
-- Enable RLS on all relevant tables
alter table public.books enable row level security;
alter table public.librarians enable row level security;
alter table public.loans enable row level security;

-- R1: Signed-in users can see the whole book catalogue; anonymous visitors cannot
create policy "R1: Signed-in users can view books" on public.books
    for select using (auth.role() = 'authenticated');

-- R2: Members can see their own loans; librarians can see every loan
create policy "R2: Members see own loans, librarians see all" on public.loans
    for select using (
        -- Members see their own loans
        (auth.role() = 'authenticated' and borrower_id = auth.uid())
        or
        -- Librarians see every loan
        exists (select 1 from public.librarians where user_id = auth.uid())
    );

-- R3: Members can borrow a book only while it has free copies and they have < 3 active loans
-- Helper function to check if a book has free copies
create or replace function public.book_has_free_copies(book_id bigint) returns boolean language sql immutable as $$
    select (select count(*) from public.loans where book_id = $1 and returned_on is null) < (select copies from public.books where id = $1);
$$;

-- Helper function to count user's active loans
create or replace function public.count_user_active_loans(borrower_id uuid) returns integer language sql immutable as $$
    select count(*) from public.loans where borrower_id = $1 and returned_on is null;
$$;

create policy "R3: Members can borrow under conditions" on public.loans
    for insert with check (
        -- Must be a signed-in user
        auth.role() = 'authenticated'
        -- Book must have free copies
        and public.book_has_free_copies(book_id)
        -- Borrower must have fewer than 3 active loans
        and public.count_user_active_loans(auth.uid()) < 3
    );

-- R4: Members can return their own active loans; nothing else can be changed
-- Prevent updates to any field except returned_on for own active loans
create policy "R4: Members can return own loans" on public.loans
    for update using (
        -- Only the borrower can return their own active loan
        auth.role() = 'authenticated'
        and borrower_id = auth.uid()
        and returned_on is null
    )
    with check (
        -- Only returned_on can be set, and only to set it (no other changes)
        -- The update must only modify returned_on
        (case when returned_on is not null then true else false end) = true
        and not (title is distinct from old.title or copies is distinct from old.copies) -- safeguard, though trigger handles it
    );

-- Trigger to enforce R4: prevent any update on returned loans, and allow only returned_on update
create trigger "tr_loans_returned_on_update"
    after update on public.loans
    for each row
    when (old.returned_on is null and new.returned_on is not null) -- only fire when setting return date on active loan
    execute function public.prevent_loan_update_except_returned_on();

-- Create the trigger function
create or replace function public.prevent_loan_update_except_returned_on() returns trigger language plpgsql as $$
begin
    -- If the loan was already returned, block all updates
    if old.returned_on is not null then
        signal sqlstate '45000' set message_text = 'Cannot modify a returned loan';
    end if;
    -- If trying to update a field other than returned_on on an active loan, block it
    if new.returned_on is null and (new.title is distinct from old.title or new.copies is distinct from old.copies or new.book_id is distinct from old.book_id or new.borrower_id is distinct from old.borrower_id) then
        signal sqlstate '45000' set message_text = 'Only returned_on can be updated on an active loan';
    end if;
    return new;
end;
$$;

-- R5: Only librarians can add books or change the catalogue; nobody can delete loans
-- Insert/update books: only librarians
create policy "R5: Librarians manage books" on public.books
    using (exists (select 1 from public.librarians where user_id = auth.uid()))
    with check (exists (select 1 from public.librarians where user_id = auth.uid()));

-- Prevent deletion of loans entirely
create policy "R5: No loan deletion" on public.loans
    using (false); -- always reject delete

-- R6: Users can see whether they themselves are a librarian; nobody can change librarians
-- View for librarian status (read-only for users)
create or replace view public.user_is_librarian as
    select auth.uid() as user_id,
           exists (select 1 from public.librarians where user_id = auth.uid()) as is_librarian;

grant select on public.user_is_librarian to authenticated;

-- R7: Anonymous visitors cannot see or change anything is handled by R1, R2, R3, R5 policies
--   which restrict to auth.role() = 'authenticated' or librarian checks.
-- R8: Server-side code using the service role keeps full access
--   service_role bypasses RLS by default; no additional grant needed.
