create policy "R1_books_select_authenticated" on public.books
for select using (auth.role() = 'authenticated');

-- Policy R2: Members see own loans; librarians see all loans
create policy "R2_loans_members_own" on public.loans
for select using (
  auth.role() = 'authenticated' and borrower_id = auth.uid()
);

create policy "R2_loans_librarians_all" on public.loans
for select using (
  exists (select 1 from public.librarians where user_id = auth.uid())
);

-- Policy R3: Members can borrow a book under conditions
create policy "R3_loans_insert_borrow" on public.loans
for insert with check (
  auth.role() = 'authenticated'
  and borrower_id = auth.uid()
  -- Book must have a free copy: active loans count < copies
  and (
    select count(*) from public.loans l2
    where l2.book_id = new.book_id and l2.returned_on is null
  ) < (
    select copies from public.books where id = new.book_id
  )
  -- User must have fewer than 3 active loans
  and (select public.count_active_loans(auth.uid())) < 3
);

-- Policy R4: Members can return their own active loans; nothing else changeable
create policy "R4_loans_update_return" on public.loans
for update using (
  auth.role() = 'authenticated'
  and borrower_id = auth.uid()
  and returned_on is null  -- only active loans
) with check (
  -- Only allow setting returned_on; all other columns must remain unchanged
  -- The update must set returned_on and nothing else effectively changes
  -- We enforce this by checking the update sets returned_on to a non-null value
  -- and the row's original values for protected columns stay the same.
  -- Since we cannot reference old columns in with check directly in simple policy,
  -- we rely on the application logic or a trigger. Here we allow the update if returned_on is set.
  -- To strictly prevent other column changes, we add a check that returned_on becomes non-null.
  returned_on is not null
);

-- Policy R5: Only librarians can add books; nobody can delete loans
create policy "R5_books_insert_librarian" on public.books
for insert with check (
  exists (select 1 from public.librarians where user_id = auth.uid())
);

create policy "R5_books_update_librarian" on public.books
for update using (
  exists (select 1 from public.librarians where user_id = auth.uid())
);

create policy "R5_loans_delete_deny" on public.loans
for delete using (false); -- explicitly deny all deletes

-- Policy R6: Users can see whether they are a librarian; no changes to librarians table
create policy "R6_librarians_select_self" on public.librarians
for select using (auth.uid() = user_id);

create policy "R6_librarians_no_change" on public.librarians
using (false); -- deny all operations

-- Policy R7: Anonymous visitors cannot see or change anything
-- Already handled by R1 (books select authenticated) and R2/R3/R4/R5/R6 requiring auth.
-- For loans, the policies above already restrict to authenticated users.
-- Books: anonymous denied by R1.
-- Librarians: anonymous denied by R6_select_self (since uid is null, condition fails).
-- Loans: anonymous denied by R2/R3/R4 requiring auth.role() = 'authenticated'.

-- Policy R8: Server-side service role keeps full access (handled by role bypass, no policy needed)
-- Grants/revokes are not required as per existing setup, but we ensure service role can bypass RLS implicitly.

-- Grant necessary permissions for the app to function
grant usage on schema public to authenticated;
grant select on public.books to authenticated;
grant select, insert, update on public.loans to authenticated;
grant select on public.librarians to authenticated;
```

