create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
as $$
declare
  from_uid uuid := auth.uid();
  from_balance integer;
  new_id bigint;
begin
  if from_uid is null then
    raise exception 'Caller is not signed in';
  end if;

  if p_amount <= 0 then
    raise exception 'Amount must be a positive integer';
  end if;

  if not exists (select 1 from public.wallets where user_id = p_to) then
    raise exception 'Recipient has no wallet';
  end if;

  if from_uid = p_to then
    raise exception 'Caller cannot send points to themselves';
  end if;

  select balance into from_balance from public.wallets where user_id = from_uid;
  if coalesce(from_balance, 0) < p_amount then
    raise exception 'Caller does not have enough points';
  end if;

  update public.wallets set balance = balance - p_amount where user_id = from_uid;
  update public.wallets set balance = balance + p_amount where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount, created_at)
  values (from_uid, p_to, p_amount, now())
  returning id into new_id;

  return new_id;
end;
$$;
