-- Enable RLS on all relevant tables
alter table public.books enable row level security;
alter table public.librarians enable row level security;
alter table public.loans enable row level security;

-- R1: Signed-in users can see the whole book catalogue; Anonymous visitors cannot
create policy "books_select_signed_in" on public.books
  using (auth.role() = 'authenticated');

-- R2: Members can see their own loans; librarians can see every loan
create policy "loans_select_members_and_librarians" on public.loans
  using (
    (auth.role() = 'authenticated' and borrower_id = auth.uid())
    or exists (select 1 from public.librarians where user_id = auth.uid())
  );

-- R3: Members can borrow a book only while copies are available and they have <3 active loans
-- Helper function to count active loans for a user
create or replace function public.count_active_loans(user_id uuid)
returns integer language sql stable as
$$
  select count(*) from public.loans
  where borrower_id = $1 and returned_on is null;
$$;

-- Policy for inserting new loans (borrowing)
create policy "loans_insert_borrow" on public.loans
  with check (
    -- Must be a signed-in user
    auth.role() = 'authenticated'
    -- Book must have free copies (active loans < copies)
    and (
      select copies from public.books where id = new.book_id
    ) > (
      select count(*) from public.loans
      where book_id = new.book_id and returned_on is null
    )
    -- User must have fewer than 3 active loans
    and (select public.count_active_loans(auth.uid())) < 3
  );

-- R4: Members can return their own active loans; nothing else can be changed
-- Trigger to prevent updates on returned loans and enforce self-return only
create or replace function public.loans_return_trigger()
returns trigger language plpgsql strict as
$$
begin
  -- If returning (returned_on is being set), allow only if currently null and user owns it
  if new.returned_on is not null and old.returned_on is null then
    -- Must be the borrower trying to return their own loan
    if new.borrower_id != auth.uid() then
      signal sqlstate '45000' set message_text = 'Only the borrower can return the loan';
    end if;
    -- Mark as returned, block further changes to other fields
    return new;
  end if;

  -- If not returning, allow update only if trying to set returned_on (handled above)
  -- Block all other updates
  signal sqlstate '45000' set message_text = 'Only returning a loan (setting returned_on) is allowed';
end;
$$;

create trigger loans_return_trigger
  after update on public.loans
  for each row
  execute function public.loans_return_trigger();

-- R5: Only librarians can add books or change the catalogue; nobody can delete loans
-- Policy for books: insert and update by librarians only
create policy "books_crud_librarians" on public.books
  using (exists (select 1 from public.librarians where user_id = auth.uid()))
  with check (exists (select 1 from public.librarians where user_id = auth.uid()));

-- Prevent deletion of loans entirely
create policy "loans_no_delete" on public.loans
  using (true)
  with check (false);

-- R6: Users can see whether they themselves are a librarian; nobody can change librarians
-- Select policy for librarians table
create policy "librarians_select_own_status" on public.librarians
  using (auth.uid() = user_id);

-- Prevent any changes to the librarians table
revoke all on public.librarians from public;
grant select on public.librarians to authenticated;
grant usage on schema public to authenticated;

-- R7: Anonymous visitors cannot see or change anything
-- The policies above already restrict anon via auth.role() checks, but explicitly deny anon access where needed
-- Books: anon already blocked by R1 policy (authenticated check)
-- Loans: anon already blocked by R2 policy (authenticated check)
-- Borrow: anon already blocked by R3 policy (authenticated check)
-- Return: anon already blocked by R4 trigger and R2 policy

-- R8: Server-side code using the service role keeps full access
-- (No explicit grant needed; service_role bypasses RLS by default in Supabase)
```

