-- Enable RLS on all relevant tables
alter table public.events enable row level security;
alter table public.invites enable row level security;
alter table public.rsvps enable row level security;

-- R1: Signed-in users can see public events. Private events visible only to host and invited users.
create policy "Public events visible to signed-in users" on public.events
  for select using (is_private = false);

create policy "Private events visible to host and invited users" on public.events
  for select using (
    is_private = true
    and (
      host_id = auth.uid()
      or exists (select 1 from public.invites where event_id = events.id and user_id = auth.uid())
    )
  );

-- R2: Signed-in users can create events as their host. Hosts can edit and delete their own events.
create policy "Users can create events as host" on public.events
  for insert with check (auth.role() = 'authenticated');

create policy "Hosts can edit own events" on public.events
  for update using (host_id = auth.uid());

create policy "Hosts can delete own events" on public.events
  for delete using (host_id = auth.uid());

-- R3: Hosts can invite people to their events and remove invitations.
-- Users can see their own invitations, hosts can see invitations to their events.
create policy "Users can see own invitations" on public.invites
  for select using (user_id = auth.uid());

create policy "Hosts can see invitations to their events" on public.invites
  for select using (
    exists (select 1 from public.events where id = event_id and host_id = auth.uid())
  );

create policy "Hosts can insert invitations to own events" on public.invites
  for insert with check (
    exists (select 1 from public.events where id = event_id and host_id = auth.uid())
  );

create policy "Hosts can delete invitations to own events" on public.invites
  for delete using (
    exists (select 1 from public.events where id = event_id and host_id = auth.uid())
  );

-- R4: Users can RSVP, as themselves, to events they can see, but only while the event has fewer RSVPs than its capacity.
-- Users can cancel their own RSVPs.
create policy "Users can RSVP to visible events with capacity" on public.rsvps
  for insert with check (
    auth.role() = 'authenticated'
    and exists (select 1 from public.events where id = event_id and (is_private = false or host_id = auth.uid() or exists (select 1 from public.invites where event_id = event_id and user_id = auth.uid())))
    and (select count(*) from public.rsvps where event_id = event_id) < (select capacity from public.events where id = event_id)
  );

create policy "Users can cancel own RSVPs" on public.rsvps
  for delete using (user_id = auth.uid());

create policy "Users can see RSVPs of event they RSVPed to" on public.rsvps
  for select using (
    exists (select 1 from public.rsvps where event_id = rsvps.event_id and user_id = auth.uid())
  );

-- R5: Hosts can see every RSVP to their events. Users can see who else has RSVPed to events they have RSVPed to.
-- Covered by the select policies above (Users can see who else has RSVPed to events they have RSVPed to via the "Users can see RSVPs of event they RSVPed to" policy).
-- Hosts seeing every RSVP is covered by the events select policy combined with the rsvps select policy for hosts.

-- R6: Anonymous visitors cannot see or change anything.
-- The policies above restrict access to signed-in users (auth.role() = 'authenticated' or auth.uid() checks).
-- No explicit anon policy needed as default is denied when RLS is enabled and no anon policy allows.

-- R7: Server-side code using the service role keeps full access.
-- service_role bypasses RLS by default in Supabase, no additional policy needed.
