create or replace function public.fn_friendships_update_trigger()
  returns trigger
  language plpgsql
  security definer
as $$
begin
  if TG_OP = 'UPDATE' then
    if new.status is distinct from old.status then
      if new.status != 'accepted' then
        raise exception 'Only status change to accepted is allowed';
      end if;
    end if;
    if (new.requester_id <> old.requester_id) or (new.addressee_id <> old.addressee_id) then
      raise exception 'Cannot change requester_id or addressee_id';
    end if;
  end if;
  return new;
end;
$$;

