```sql
-- Enable RLS on all relevant tables
alter table public.restaurants enable row level security;
alter table public.restaurant_staff enable row level security;
alter table public.reservations enable row level security;

-- R1: Users can see restaurants; guests see own reservations, staff see their restaurant's reservations
create policy "Users can view restaurants" on public.restaurants
  for select using (true);

create policy "Guests see own reservations, staff see restaurant reservations" on public.reservations
  for select using (
    -- Guests see their own reservations
    auth.uid() = user_id
    or
    -- Staff see reservations at their restaurant
    exists (
      select 1 from public.restaurant_staff rs
      where rs.restaurant_id = reservations.restaurant_id
      and rs.user_id = auth.uid()
    )
  );

-- R2: Guests can book only for future time, new reservations are 'booked'
create policy "Guests can insert future reservations" on public.reservations
  for insert with check (
    auth.uid() = user_id
    and reserved_for > now()
    and status = 'booked'
  );

-- R3: Guests can cancel own booked reservations while in future
create policy "Guests can cancel own future reservations" on public.reservations
  for update using (
    auth.uid() = user_id
    and status = 'booked'
    and reserved_for > now()
  )
  with check (
    auth.uid() = user_id
    and status = 'cancelled'
    and (case when status = 'cancelled' then reserved_for > now() else true end)
  );

-- R4: Staff can mark booked as seated/no_show after reservation time has passed
create policy "Staff can update reservations after time has passed" on public.reservations
  for update using (
    exists (
      select 1 from public.restaurant_staff rs
      where rs.restaurant_id = reservations.restaurant_id
      and rs.user_id = auth.uid()
    )
    and reserved_for < now()
  )
  with check (
    exists (
      select 1 from public.restaurant_staff rs
      where rs.restaurant_id = reservations.restaurant_id
      and rs.user_id = auth.uid()
    )
    and reserved_for < now()
    and status in ('seated', 'no_show')
  );

-- R5: Restaurants and staff lists cannot be changed; reservations never deleted
-- (No insert/update/delete policies needed as RLS defaults restrict; we explicitly prevent DML on restaurants/staff)
create policy "No modifications to restaurants" on public.restaurants
  using (false);

create policy "No modifications to restaurant_staff" on public.restaurant_staff
  using (false);

create policy "Reservations never deleted" on public.reservations
  using (false);

-- R6: Anonymous visitors cannot see or change anything
-- RLS policies above already restrict to authenticated users via auth.uid()
-- Additional policy to explicitly block anon if needed:
create policy "Block anonymous access" on public.reservations
  using (false);

create policy "Block anonymous restaurant access" on public.restaurants
  using (false);

create policy "Block anonymous staff access" on public.restaurant_staff
  using (false);

-- R7: Server-side code using service role keeps full access
-- service_role bypasses RLS by default; no additional policy needed.
-- Grant service_role full access if not already granted:
grant all on public.restaurants to service_role;
grant all on public.restaurant_staff to service_role;
grant all on public.reservations to service_role;
```

