```sql
-- Enable Row Level Security on all tables
alter table public.surveys enable row level security;
alter table public.survey_responses enable row level security;
alter table public.survey_results enable row level security;

-- Policies for surveys
-- R1: Signed-in users can see every survey
create policy "Users can view all surveys" on public.surveys
  for select using (true);

-- R1: Users can create surveys as their owner
create policy "Users can insert their own surveys" on public.surveys
  for insert with check (auth.uid() = owner_id);

-- R1: Users can rename their own surveys
create policy "Users can update own surveys" on public.surveys
  for update using (auth.uid() = owner_id)
  with check (auth.uid() = owner_id);

-- Policies for survey_responses
-- R2: Respondents can CRUD their own response
create policy "Respondents can manage own response" on public.survey_responses
  for all using (respondent_id = auth.uid())
  with check (respondent_id = auth.uid());

-- R3: Nobody else can read individual responses (including owner)
-- The above policy already ensures only the respondent can read their own row.
-- Additional deny for owner/others is implicit via the primary key constraint and policy.

-- View: survey_results
-- R4: View showing owned surveys with >= 3 responses
create view public.survey_results as
select
  s.id as survey_id,
  count(sr.id) as responses,
  round(cast(avg(sr.score) as numeric), 2) as avg_score
from public.surveys s
left join public.survey_responses sr on s.id = sr.survey_id
group by s.id
having count(sr.id) >= 3;

-- R5: Anonymous visitors cannot see or change anything
-- The view and tables rely on RLS; anon role has no access by default.
-- We explicitly deny anon access to be safe.
revoke all on public.surveys from anon;
revoke all on public.survey_responses from anon;
revoke all on public.survey_results from anon;

-- R6: Service role keeps full access
grant all on public.surveys to service_role;
grant all on public.survey_responses to service_role;
grant all on public.survey_results to service_role;
grant usage on schema public to service_role;
