-- Enable RLS on both tables
alter table public.incidents enable row level security;
alter table public.incident_updates enable row level security;

-- Rule R1: Anyone can read published incidents
create policy "Public can read published incidents"
  on public.incidents for select
  using (is_published = true);

-- Rule R2: Anyone can read published updates belonging to published incidents
-- This is enforced via a join check in the policy
create policy "Public can read published updates"
  on public.incident_updates for select
  using (
    is_published = true 
    and exists (
      select 1 from public.incidents i
      where i.id = incident_id
      and i.is_published = true
    )
  );

-- Rule R3: Unpublished incidents and updates are visible only to server-side code
-- Since RLS is enabled and the above policies only allow reading published rows,
-- any row where is_published = false will be inaccessible to anon/non-service users.
-- No additional policy needed; the default behavior blocks access.

-- Rule R4: Nobody can create, change or delete incidents or updates through the app
-- Deny all DML operations for anon and authenticated users
create policy "Deny DML for anon/authed users on incidents"
  on public.incidents for all
  to anon, authenticated
  using (false)
  with check (false);

create policy "Deny DML for anon/authed users on incident_updates"
  on public.incident_updates for all
  to anon, authenticated
  using (false)
  with check (false);

-- Rule R5: Server-side code using service role keeps full access
-- No explicit grant needed; service_role bypasses RLS by default.
-- However, we explicitly grant usage so the intent is clear.
grant all on public.incidents to service_role;
grant all on public.incident_updates to service_role;

-- Grant select for anon and authenticated users (for published rows only)
grant select (id, title, severity, status, is_published) on public.incidents to anon, authenticated;
grant select (id, incident_id, body, is_published) on public.incident_updates to anon, authenticated;
