    using (user_id is null or user_id = auth.uid());

-- R2: Users can create, update, delete only their own categories
create policy "R2_manage_own_categories" on public.categories
    for all
    using (user_id = auth.uid())
    with check (user_id = auth.uid());

-- R3: Prevent creation of built-in categories and prevent user categories becoming built-in
-- Trigger to enforce that user_id is always set on insert/update
create function public.ensure_user_category()
    returns trigger as
$$
begin
    -- Prevent inserting a category without a user_id (blocks built-in creation)
    if new.user_id is null then
        raise exception 'Built-in categories cannot be created through the app';
    end if;
    -- Prevent updating user_id to null (blocks turning a user category into built-in)
    if new.user_id is null and TG_OP = 'UPDATE' then
        raise exception 'A user category cannot be turned into a built-in category';
    end if;
    return new;
end;
$$
language plpgsql security definer;

create trigger ensure_user_category_trigger
    before insert or update on public.categories
    for each row
    execute function public.ensure_user_category();

-- R4: Anonymous visitors cannot see or change any categories
-- (RLS is enabled, and anon role has no permissions; explicitly deny to be safe)
revoke all on public.categories from anon;

-- R5: Server-side code using the service role keeps full access
grant all on public.categories to service_role;
