on public.categories for select
using (
  -- Built-in categories have no user_id
  user_id is null
  or user_id = auth.uid()
);

-- R2: Users can create categories only for themselves
create policy "Users can create own categories"
on public.categories for insert
with check (user_id = auth.uid());

-- R2: Users can edit only their own categories
create policy "Users can update own categories"
on public.categories for update
using (user_id = auth.uid())
with check (user_id = auth.uid());

-- R2: Users can delete only their own categories
create policy "Users can delete own categories"
on public.categories for delete
using (user_id = auth.uid());

-- R3: Prevent creating/updating categories to/from built-in status
-- Trigger to prevent inserting categories with user_id (built-in categories)
create function public.prevent_built_in_insert()
returns trigger as $$
begin
  -- Built-in categories have no user_id; reject inserts that set user_id
  if new.user_id is not null then
    raise exception 'Cannot create a category with a user_id (built-in categories are shared)';
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger prevent_built_in_insert
before insert on public.categories
for each row execute function public.prevent_built_in_insert();

-- Trigger to prevent updating user_id (prevent user's category becoming built-in, or built-in being changed)
create function public.prevent_built_in_update()
returns trigger as $$
begin
  -- Reject updates that set or remove user_id
  if new.user_id is distinct from coalesce(old.user_id, '') then
    raise exception 'Cannot change the user_id of a category';
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger prevent_built_in_update
before update on public.categories
for each row execute function public.prevent_built_in_update();

-- R4: Anonymous visitors cannot see or change any categories
create policy "Anonymous access denied"
on public.categories for all
using (false)
with check (false);

