  passenger_id = auth.uid() OR 
  EXISTS (SELECT 1 FROM public.rides WHERE id = ride_id AND driver_id = auth.uid())
);
CREATE POLICy "Passengers can request seats" ON public.ride_bookings FOR INSERT TO authenticated USING (
  auth.uid() = passenger_id AND 
  EXISTS (SELECT 1 FROM public.rides WHERE id = ride_id AND departs_at > now() AND driver_id != auth.uid())
);
CREATE POLICy "Drivers can confirm/decline before departure" ON public.ride_bookings FOR UPDATE TO authenticated USING (
  EXISTS (SELECT 1 FROM public.rides WHERE id = ride_id AND driver_id = auth.uid())
  AND departs_at > now()
);
CREATE POLICy "Passengers can withdraw own bookings" ON public.ride_bookings FOR DELETE TO authenticated USING (
  passenger_id = auth.uid() AND EXISTS (SELECT 1 FROM public.rides WHERE id = ride_id AND departs_at > now())
);

CREATE OR REPLACE FUNCTION public.validate_booking_update()
RETURNS trigger AS $$
BEGIN
  IF NEW.ride_id != OLD.ride_id THEN
    RAISE EXCEPTION 'ride_id cannot be modified';
  END IF;
  IF NEW.passenger_id != OLD.passenger_id THEN
    RAISE EXCEPTION 'passenger_id cannot be modified';
  END IF;
  IF NEW.status = 'confirmed' THEN
    IF (SELECT seats FROM public.rides WHERE id = NEW.ride_id) <= 
       (SELECT COUNT(*) FROM public.ride_bookings WHERE ride_id = NEW.ride_id AND status = 'confirmed') THEN
      RAISE EXCEPTION 'Cannot confirm: ride is at full capacity';
    END IF;
  END IF;

