  passenger_id = auth.uid()
  or ride_id in (select id from public.rides where driver_id = auth.uid())
);

create policy "bookings_insert_request" on public.ride_bookings for insert to authenticated with check (
  passenger_id = auth.uid()
  and status = 'requested'
  and ride_id in (select id from public.rides where departs_at > now() and driver_id != auth.uid())
);

create policy "bookings_delete_withdraw" on public.ride_bookings for delete to authenticated using (
  passenger_id = auth.uid()
  and ride_id in (select id from public.rides where departs_at > now())
);

create policy "bookings_update_driver" on public.ride_bookings for update to authenticated using (
  ride_id in (select id from public.rides where driver_id = auth.uid())
  and exists (select 1 from public.rides r where r.id = ride_id and r.departs_at > now())
);

create or replace function fn_ride_booking_update_check()
  returns trigger
  language plpgsql
  security definer
as $$
declare
  confirmed_count integer;
  ride_seats integer;
begin
  if TG_OP = 'UPDATE' then
    if (new.passenger_id is distinct from old.passenger_id) or
       (new.ride_id is distinct from old.ride_id) then
      raise exception 'Only the status column can be modified on ride_bookings.';
    end if;
  end if;

  if new.status = 'confirmed' then
    select count(*) into confirmed_count
    from public.ride_bookings
    where ride_id = new.ride_id and status = 'confirmed';

    select seats into ride_seats
    from public.rides
    where id = new.ride_id;

    if confirmed_count >= ride_seats then
      raise exception 'Cannot confirm: ride has no available seats.';
    end if;
  end if;

  return new;
end;
$$;

create trigger trg_ride_booking_update_check
  before update on public.ride_bookings
  for each row
  execute function fn_ride_booking_update_check();
