    case
      when exists (select 1 from public.purchase_orders where id = p_po_id) then
        -- Amount must be within approver's limit
        (select limit_amount from public.approvers where user_id = p_approver_id) >=
        (select amount from public.purchase_orders where id = p_po_id)
        and
        -- Approver must not have requested the PO
        (select requester_id from public.purchase_orders where id = p_po_id) != p_approver_id
      else false
    end;
$$;

