create or replace function public.user_folder_access(p_user_id uuid, p_folder_id bigint, p_edit boolean default false)
returns boolean
language sql stable
set search_path = public
as $$
with recursive ancestors as (
  select id, owner_id from public.folders where id = p_folder_id
  union all
  select f.id, f.owner_id from public.folders f join ancestors a on f.id = a.parent_id
)
select bool_or(
  owner_id = p_user_id,
  exists (
    select 1 from public.folder_grants fg
    where fg.folder_id = a.id
    and fg.user_id = p_user_id
    and (not p_edit or fg.can_edit = true)
  )
) from ancestors;
$$;

