  for delete to authenticated
  using (false);

create or replace function public.approve_access(p_request_id bigint)
  returns text
  language plpgsql
  security definer
as $$
declare
  v_status text;
  v_approver_count integer;
begin
  if not exists (select 1 from public.access_requests where id = p_request_id) then
    raise exception 'Request with id % does not exist.', p_request_id using errcode = 'invalid_parameter_value';
  end if;

  if (select status from public.access_requests where id = p_request_id) != 'pending' then
    raise exception 'Request with id % is not pending.', p_request_id using errcode = 'invalid_parameter_value';
  end if;

  if auth.role() != 'service_role' then
    if not exists (select 1 from public.ops_team where user_id = auth.uid()) then
      raise exception 'Caller is not on the ops team.';
    end if;
  end if;

  if exists (select 1 from public.access_requests where id = p_request_id and requester_id = auth.uid()) then
    raise exception 'Caller cannot approve their own request.';
  end if;

  if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = auth.uid()) then
    raise exception 'Caller has already approved this request.';
  end if;

  insert into public.access_approvals (request_id, approver_id)
    values (p_request_id, auth.uid());

  select count(distinct approver_id) into v_approver_count
    from public.access_approvals
    where request_id = p_request_id;

  if v_approver_count >= 2 then
    update public.access_requests set status = 'granted' where id = p_request_id;
  end if;

  return (select status from public.access_requests where id = p_request_id);
end;
$$;

grant execute on function public.approve_access(p_request_id bigint) to authenticated;
