returns text
language plpgsql
security definer
as $$
declare
  v_status text;
  v_approver_count int;
  v_is_ops bool;
  v_requester_id uuid;
begin
  if not exists (select 1 from public.access_requests where id = p_request_id) then
    raise exception 'Request ID % does not exist.', p_request_id using errhint = ' ';
