```sql
-- Enable Row Level Security on all relevant tables
alter table public.folders enable row level security;
alter table public.folder_grants enable row level security;
alter table public.documents enable row level security;

-- Helper function: checks if a user has access to a folder (read or edit)
create function public.folder_accessible(user_id uuid, folder_id bigint, edit boolean default false)
  returns boolean
language sql
stable
set search_path = public
as $$
with recursive ancestors as (
  select id from public.folders where id = folder_id
  union all
  select f.id from public.folders f join ancestors a on f.id = a.parent_id
)
select
  (exists(select 1 from ancestors a where a.owner_id = user_id))
  or (edit and exists(select 1 from public.folder_grants fg where fg.folder_id = any(select id from ancestors) and fg.user_id = user_id and fg.can_edit = true))
  or (not edit and exists(select 1 from public.folder_grants fg where fg.folder_id = any(select id from ancestors) and fg.user_id = user_id))
$$;

-- Helper function: checks if a user owns a folder or any ancestor folder
create function public.user_owns_folder(user_id uuid, folder_id bigint)
  returns boolean
language sql
stable
set search_path = public
as $$
with recursive ancestors as (
  select id from public.folders where id = folder_id
  union all
  select f.id from public.folders f join ancestors a on f.id = a.parent_id
)
select exists(select 1 from ancestors a where a.owner_id = user_id)
$$;

-- Folders policies
create policy "Folders select" on public.folders
  for select using (auth.role() = 'authenticated' and public.folder_accessible(auth.uid(), id, false));

create policy "Folders insert" on public.folders
  for insert with check (
    auth.role() = 'authenticated'
    and (
      parent_id is null
      or public.folder_accessible(auth.uid(), parent_id, false)
    )
  );

create policy "Folders update" on public.folders
  for update using (
    auth.role() = 'authenticated' and public.folder_accessible(auth.uid(), id, true)
  );

create policy "Folders delete" on public.folders
  for delete using (
    auth.role() = 'authenticated' and public.folder_accessible(auth.uid(), id, true)
  );

-- Folder grants policies
create policy "Folder grants select" on public.folder_grants
  for select using (
    auth.role() = 'authenticated'
    and (user_id = auth.uid() or public.folder_accessible(auth.uid(), folder_id, false))
  );

create policy "Folder grants manage" on public.folder_grants
  for all using (
    auth.role() = 'authenticated' and public.user_owns_folder(auth.uid(), folder_id)
  ) with check (
    auth.role() = 'authenticated' and public.user_owns_folder(auth.uid(), folder_id)
  );

-- Documents policies
create policy "Documents select" on public.documents
  for select using (auth.role() = 'authenticated' and public.folder_accessible(auth.uid(), folder_id, false));

create policy "Documents insert" on public.documents
  for insert with check (
    auth.role() = 'authenticated' and public.folder_accessible(auth.uid(), folder_id, true)
  );

create policy "Documents update" on public.documents
  for update using (
    auth.role() = 'authenticated' and public.folder_accessible(auth.uid(), folder_id, true)
  )
  with check (
    auth.role() = 'authenticated' and public.folder_accessible(auth.uid(), folder_id, true)
  );

create policy "Documents delete" on public.documents
  for delete using (
    auth.role() = 'authenticated' and public.folder_accessible(auth.uid(), folder_id, true)
  );

-- Grants and revokes to enforce access rules and role behavior
grant usage on schema public to authenticated;
revoke all on public.folders from anon;
revoke all on public.folder_grants from anon;
revoke all on public.documents from anon;
-- Service role retains full access by default (bypasses RLS)
```

