alter table public.providers enable row level security;
alter table public.slots enable row level security;

-- R1: Signed-in users can see the list of providers
create policy "Providers are viewable by signed-in users" on public.providers
  for select using (auth.role() = 'authenticated');

-- R2: Patients can see open future slots and their own bookings; Providers see their own slots with booking info
create policy "Slots are viewable by role-specific rules" on public.slots
  for select using (
    -- Open future slots visible to all authenticated users
    (booked_by is null and starts_at > now()) 
    -- Or slots booked by the current user
    or booked_by = auth.uid()
    -- Providers see all their own slots including who booked them
    or exists (
      select 1 from public.providers p
      where p.user_id = auth.uid()
      and p.user_id = provider_id
    )
  );

-- R3: A patient can book an open future slot for themselves
create policy "Patients can book open future slots" on public.slots
  for insert with check (
    auth.role() = 'authenticated'
    and booked_by = auth.uid()
    and starts_at > now()
    and not exists (
      select 1 from public.slots s2
      where s2.id = slots.id
      and (s2.booked_by is not null or s2.starts_at <= now())
    )
  );

-- R4: A patient can cancel their own booking while the slot is still in the future
create policy "Patients can cancel own booking" on public.slots
  for update using (
    auth.role() = 'authenticated'
    and booked_by = auth.uid()
    and starts_at > now()
  );

-- R5: Nobody can create, move or delete slots, or change anything else about them
-- Prevent inserts via the app (R3 handles the specific allowed insert, but we add a restrictive check to be safe)
create policy "No slot inserts via app" on public.slots
  for insert with check (false);
-- Prevent updates that change core fields
create policy "No slot updates via app" on public.slots
  for update using (false);
-- Prevent deletes
create policy "No slot deletes via app" on public.slots
  for delete using (false);

-- R6: Anonymous visitors cannot see or change anything
-- Already handled by the auth.role() = 'authenticated' checks above, 
-- but explicitly deny anon access for clarity
create policy "Anonymous access denied on providers" on public.providers
  for all using (false);
create policy "Anonymous access denied on slots" on public.slots
  for all using (false);

-- R7: Server-side code using the service role keeps full access
-- Grant service_role full access (bypasses RLS automatically, but explicit grant for clarity)
grant all on public.providers to service_role;
grant all on public.slots to service_role;
