grant usage on schema public to authenticated;
grant select on public.pharmacists to authenticated;
grant select, insert, update, delete on public.prescriptions to service_role;
grant select, insert, update, delete on public.dispenses to service_role;

-- Revoke direct DML on prescriptions/dispenses for authenticated to enforce RLS
revoke all on public.prescriptions from authenticated;
revoke all on public.dispenses from authenticated;

-- Grant execute on the dispense function to authenticated users (pharmacists)
grant execute on function public.dispense(bigint) to authenticated;
