create function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
as $$
declare
  v_user uuid := auth.uid();
  v_doc_exists boolean;
  v_has_edit boolean;
begin
  if v_user is null then
    raise exception 'Access denied';
  end if;

  select exists(1 into v_doc_exists from public.documents where id = p_doc_id);
  if not v_doc_exists then
    raise exception 'Document does not exist';
  end if;

  select exists(1 into v_has_edit from public.doc_access where doc_id = p_doc_id and user_id = v_user and can_edit = true);
  if not v_has_edit then
    raise exception 'User does not have edit access to this document';
  end if;

  if exists (select 1 from public.documents where id = p_doc_id and checked_out_by = v_user) then
    return;
  end if;

  if exists (select 1 from public.documents where id = p_doc_id and checked_out_by is not null and checked_out_by != v_user) then
    raise exception 'Document is already checked out by another user';
  end if;

  update public.documents set checked_out_by = v_user where id = p_doc_id;
end;
$$;

create function public.checkin_document(p_doc_id bigint, p_body text)
returns void
language plpgsql
security definer
as $$
begin
  if auth.uid() is null then
    raise exception 'Access denied';
  end if;

  if not exists (select 1 from public.documents where id = p_doc_id and checked_out_by = auth.uid()) then
    raise exception 'Document is not checked out by this user';
  end if;

  update public.documents set body = p_body, checked_out_by = null where id = p_doc_id;
end;
$$;

grant execute on public.checkout_document to authenticated;
grant execute on public.checkin_document to authenticated;
