CREATE OR REPLACE FUNCTION public.checkout_document(p_doc_id bigint)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO public
AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.documents WHERE id = p_doc_id) THEN
    RAISE EXCEPTION 'Document with id % does not exist.', p_doc_id USING ERRCODE = 'undefined_table';
  END IF;

