    RAISE EXCEPTION 'You do not have edit access to document with id %.', p_doc_id;
  END IF;

  IF EXISTS (SELECT 1 FROM public.documents WHERE id = p_doc_id AND checked_out_by IS NOT NULL AND checked_out_by != auth.uid()) THEN
    RAISE EXCEPTION 'Document with id % is already checked out by another user.', p_doc_id;
  END IF;

  UPDATE public.documents
  SET checked_out_by = auth.uid()
  WHERE id = p_doc_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.checkin_document(p_doc_id bigint, p_body text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO public
AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.documents WHERE id = p_doc_id AND checked_out_by = auth.uid()) THEN
    RAISE EXCEPTION 'You do not have document with id % checked out.', p_doc_id;
  END IF;

  UPDATE public.documents
  SET body = p_body, checked_out_by = NULL
  WHERE id = p_doc_id;
END;
$$;

GRANT SELECT ON public.documents TO authenticated;
GRANT SELECT ON public.doc_access TO authenticated;
GRANT EXECUTE ON FUNCTION public.checkout_document TO authenticated;
GRANT EXECUTE ON FUNCTION public.checkin_document TO authenticated;
