create or replace public function checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
    if auth.role() = 'anon' then
        raise exception 'Anonymous users cannot check out documents';
    end if;

    if not exists (select 1 from public.documents where id = p_doc_id) then
        raise exception 'Document does not exist';
    end if;

    if not exists (select 1 from public.doc_access where doc_id = p_doc_id and user_id = auth.uid() and can_edit = true) then
        raise exception 'User does not have edit access to this document';
    end if;

    if exists (select 1 from public.documents where id = p_doc_id and checked_out_by is not null and checked_out_by != auth.uid()) then
        raise exception 'Document is already checked out by another user';
    end if;

    if (select checked_out_by from public.documents where id = p_doc_id) = auth.uid() then
        return;
    end if;

    update public.documents set checked_out_by = auth.uid() where id = p_doc_id;
end;
$$;

create or replace public function checkin_document(p_doc_id bigint, p_body text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
    if auth.role() = 'anon' then
        raise exception 'Anonymous users cannot check in documents';
    end if;

    if not exists (select 1 from public.documents where id = p_doc_id) then
        raise exception 'Document does not exist';
    end if;

    if (select checked_out_by from public.documents where id = p_doc_id) != auth.uid() then
        raise exception 'Document is not checked out by the current user';
    end if;

    update public.documents set body = p_body, checked_out_by = null where id = p_doc_id;
end;
$$;

