  for select using (user_id = auth.uid());

create policy "Users can see own staff assignment" on public.building_staff
  for select using (user_id = auth.uid());

-- R1: Residents see own units; staff see units in their buildings
create policy "Residents see own units" on public.units
  for select using (id in (select unit_id from public.residents where user_id = auth.uid()));

create policy "Staff see units in their buildings" on public.units
  for select using (exists (select 1 from public.building_staff where building_staff.building_id = (select building_id from public.units where id = units.id) and building_staff.user_id = auth.uid()));

-- R2: Residents create requests for own units
create policy "Residents create requests" on public.requests
  for insert with check (created_by = auth.uid() and unit_id in (select unit_id from public.residents where user_id = auth.uid()));

-- R1: Staff see requests of units in their buildings
create policy "Staff see requests in their buildings" on public.requests
  for select using (exists (select 1 from public.units join public.building_staff on units.building_id = building_staff.building_id where units.id = requests.unit_id and building_staff.user_id = auth.uid()));

-- R3: Residents and staff can add photos to requests they can see
create policy "Residents and staff add photos" on public.request_photos
  for insert with check (exists (select 1 from public.requests where id = request_id and (unit_id in (select unit_id from public.residents where user_id = auth.uid()) or exists (select 1 from public.units join public.building_staff on units.building_id = building_staff.building_id where units.id = requests.unit_id and building_staff.user_id = auth.uid()))));

-- R4: Staff can change status; nobody else can change anything else
create policy "Staff update status" on public.requests
  for update using (exists (select 1 from public.units join public.building_staff on units.building_id = building_staff.building_id where units.id = requests.unit_id and building_staff.user_id = auth.uid()));

-- R4: Residents cannot change status (prevent all other updates)
create policy "Residents cannot update requests" on public.requests
  for update using (false);

-- R4: Requests are never deleted
create policy "Requests never deleted" on public.requests
  for delete using (false);

-- R5: Users can see their own residence and staff rows (already covered, but explicit grant for clarity)
grant select on public.residents to authenticated;
grant select on public.building_staff to authenticated;

-- R6: Anonymous visitors cannot see or change anything (default deny)
-- No policies for anon role needed as they default to no access on enabled RLS tables

-- R7: Server-side code using the service role keeps full access (handled by role bypass)
