```sql
-- Enable RLS on all relevant tables
alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

-- Helper function: get current user's building IDs
create or replace function public.get_user_building_ids()
returns setof bigint language sql stable security invoker as $$
  select building_id from public.building_staff where user_id = auth.uid();
$$;

-- Helper function: check if user is a resident of a unit
create or replace function public.is_resident_of(unit_id bigint)
returns boolean language sql stable security invoker as $$
  select exists (
    select 1 from public.residents where unit_id = is_resident_of.unit_id and user_id = auth.uid()
  );
$$;

-- Helper function: check if user is building staff
create or replace function public.is_building_staff()
returns boolean language sql stable security invoker as $$
  select exists (
    select 1 from public.building_staff where user_id = auth.uid()
  );
$$;

-- Policy: Residents see their own units; staff see all units in their buildings
create policy "residents_see_own_units" on public.units
  for select using (public.is_resident_of(id));

create policy "staff_see_units_in_buildings" on public.units
  for select using (
    public.is_building_staff() and
    id in (select building_staff.building_id from public.building_staff where building_staff.user_id = auth.uid())
  );

-- Policy: Residents see their own requests and photos
create policy "residents_see_own_requests" on public.requests
  for select using (public.is_resident_of(unit_id));

create policy "residents_see_own_photos" on public.request_photos
  for select using (
    exists (
      select 1 from public.requests where id = request_photos.request_id and public.is_resident_of(unit_id)
    )
  );

-- Policy: Staff see all requests and photos in their buildings
create policy "staff_see_all_requests" on public.requests
  for select using (public.is_building_staff());

create policy "staff_see_all_photos" on public.request_photos
  for select using (
    exists (
      select 1 from public.requests where id = request_photos.request_id
    ) and public.is_building_staff()
  );

-- Policy: Residents create requests for their own units (status defaults to 'open')
create policy "residents_create_requests" on public.requests
  for insert with check (
    public.is_resident_of(unit_id) and
    created_by = auth.uid()
  );

-- Policy: Residents and staff can add photos to visible requests
create policy "residents_and_staff_add_photos" on public.request_photos
  for insert with check (
    exists (
      select 1 from public.requests r
      where r.id = request_id
      and (
        public.is_resident_of(r.unit_id)
        or public.is_building_staff()
      )
    )
  );

-- Policy: Staff can update status; nobody else can change requests
create policy "staff_update_status" on public.requests
  for update using (
    public.is_building_staff()
  ) with check (
    public.is_building_staff() and
    status in ('open', 'in_progress', 'done')
  );

-- Policy: No deletions on requests
create policy "no_delete_requests" on public.requests
  for delete using (false);

-- Policy: Residents see their own residence row
create policy "residents_see_own_residence" on public.residents
  for select using (user_id = auth.uid());

-- Policy: Staff see their own staff row
create policy "staff_see_own_staff" on public.building_staff
  for select using (user_id = auth.uid());

-- Policy: Nobody modifies units, residents or staff through the app
create policy "no_modify_units" on public.units
  for all using (false);

create policy "no_modify_residents" on public.residents
  for all using (false);

create policy "no_modify_building_staff" on public.building_staff
  for all using (false);

-- Grant access to authenticated users (residents and staff)
grant usage on schema public to authenticated;
grant select on public.units to authenticated;
grant select on public.residents to authenticated;
grant select on public.building_staff to authenticated;
grant select, insert, update on public.requests to authenticated;
grant select, insert on public.request_photos to authenticated;

-- Service role keeps full access (bypasses RLS)
grant all on public.units to service_role;
grant all on public.residents to service_role;
grant all on public.building_staff to service_role;
grant all on public.requests to service_role;
grant all on public.request_photos to service_role;
```

