-- Enable RLS on both tables
alter table public.items enable row level security;
alter table public.claims enable row level security;

-- Helper function to check if current user is the finder of a given item
create function public.is_finder_of_item(item_id bigint) returns boolean language sql immutable strict as $$
  select exists (
    select 1 from public.items
    where id = item_id
    and found_by = auth.uid()
  );
$$;

-- RLS POLICIES for items

-- R1: Signed-in users can see every item
create policy "Users can view items" on public.items
  for select using (auth.role() = 'authenticated');

-- R1: Finders can post items as themselves (always open)
create policy "Finders can insert items" on public.items
  for insert with check (auth.role() = 'authenticated' and found_by = auth.uid());

-- R1: Finders can change their own items
create policy "Finders can update own items" on public.items
  for update using (auth.role() = 'authenticated' and found_by = auth.uid());

-- R5: Anonymous visitors cannot see or change anything
-- (Implicitly handled by the authenticated check above, but explicit deny for anon)
create policy "Anonymous cannot access items" on public.items
  for all using (auth.role() != 'authenticated');

-- RLS POLICIES for claims

-- R2: Claimants can see their own claims; finders can see every claim on their items
create policy "Claimants can view own claims" on public.claims
  for select using (auth.role() = 'authenticated' and claimant_id = auth.uid());

create policy "Finders can view claims on their items" on public.claims
  for select using (auth.role() = 'authenticated' and exists (
    select 1 from public.items where id = item_id and found_by = auth.uid()
  ));

-- R3: Users can claim open items they did not find, as themselves; new claims are always pending
create policy "Users can insert claims" on public.claims
  for insert with check (auth.role() = 'authenticated' and claimant_id = auth.uid() and status = 'pending');

-- R2/R3: Signed-in users can see claims matching the rules above (already covered by select policies)

-- R4: Only the finder can approve or reject a pending claim on their item; at most one approved claim per item; claimants can never change status; nothing else about a claim can change
-- Prevent claimants (or anyone else) from updating claim status
create policy "Claimants cannot update claim status" on public.claims
  for update using (false); -- base case: no updates allowed by claimants

-- Allow finders to update claim status (approve/reject) on their items
create policy "Finders can update claim status" on public.claims
  for update using (auth.role() = 'authenticated' and exists (
    select 1 from public.items where id = item_id and found_by = auth.uid()
  ));

-- Enforce: an item can have at most one approved claim
-- This is enforced via a partial unique index and a check, but we add a policy-level guard for RLS visibility/control
-- Note: The actual constraint is best added as a unique index; here we ensure RLS does not block the constraint logic.
-- We do not create triggers here as per instructions to only use the specified objects; the constraint can be a separate index if needed, but we stick to the required objects.

-- R5: Anonymous visitors cannot see or change anything
create policy "Anonymous cannot access claims" on public.claims
  for all using (auth.role() != 'authenticated');

-- R6: Server-side code using the service role keeps full access
-- (No explicit policy needed; service_role bypasses RLS by default in Supabase)

-- Grants for anon role (ensure anon cannot bypass; explicitly revoke if needed)
-- Since R5 requires anon cannot see/change, we revoke any implicit grants
revoke all on public.items from anon;
revoke all on public.claims from anon;

-- Grant service_role full access (already implicit, but explicit for clarity)
grant all on public.items to service_role;
grant all on public.claims to service_role;
