  for update using (is_finder(id));

-- R2: Claims
-- Finders can see every claim on their items
create policy "Finders see all claims on their items" on public.claims
  for select using (
    exists (select 1 from public.items where id = item_id and found_by = auth.uid())
  );

-- Claimants can see their own claims
create policy "Claimants see own claims" on public.claims
  for select using (claimant_id = auth.uid());

