-- Claimants cannot update claims
create policy "Claimants cannot update claims" on public.claims
  for update using (false); -- always reject, effectively blocking all updates by claimants

-- Finders can approve/reject pending claims on their items
create policy "Finders can approve/reject claims" on public.claims
  for update using (
    is_finder(item_id)
    and status in ('approved', 'rejected')
    and exists (
      select 1 from public.claims c2
      where c2.item_id = item_id
        and c2.status = 'approved'
        and c2.id != id  -- ensure only one approved claim per item
    )
  );

