--  but we explicitly deny to be safe)
create policy "Anonymous denied all" on public.items
  for all using (false);
create policy "Anonymous denied all claims" on public.claims
  for all using (false);

-- R6: Service role keeps full access (implicit via bypass, but explicit grant for clarity)
grant all on public.items to service_role;
grant all on public.claims to service_role;
