    AND auth.uid() != (SELECT seller_id FROM public.listings WHERE id = listing_id)
);

CREATE OR REPLACE FUNCTION public.mark_shipped(p_order_id bigint)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    UPDATE public.orders
    SET status = 'shipped'
    WHERE id = p_order_id
      AND status = 'paid'
      AND seller_id = auth.uid();

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cannot mark shipped: order not found, not in paid status, or you are not the seller.';
    END IF;

    RETURN 'shipped';
END;
$$;

CREATE OR REPLACE FUNCTION public.release_funds(p_order_id bigint)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    UPDATE public.orders
    SET status = 'released'
    WHERE id = p_order_id
      AND status = 'shipped'
      AND buyer_id = auth.uid();

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cannot release funds: order not found, not in shipped status, or you are not the buyer.';
    END IF;

    RETURN 'released';
END;
$$;

CREATE OR REPLACE FUNCTION public.refund_order(p_order_id bigint)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    UPDATE public.orders
    SET status = 'refunded'
    WHERE id = p_order_id
      AND status IN ('paid', 'shipped')
      AND seller_id = auth.uid();

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cannot refund: order not found, not in allowed status, or you are not the seller.';
    END IF;

    RETURN 'refunded';
END;
$$;

GRANT SELECT ON public.listings TO authenticated;
GRANT INSERT ON public.orders TO authenticated;
GRANT EXECUTE ON FUNCTION public.mark_shipped TO authenticated;
GRANT EXECUTE ON FUNCTION public.release_funds TO authenticated;
GRANT EXECUTE ON FUNCTION public.refund_order TO authenticated;
