create or replace function public.mark_shipped(p_order_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_order public.orders%rowtype;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order with id % not found.', p_order_id using errhint = 'Order does not exist.';
  end if;
  if v_order.status != 'paid' then
    raise exception 'Order is not in paid status. Current status: %.', v_order.status using errhint = 'Only orders in paid status can be marked shipped.';
  end if;
  if v_order.seller_id != auth.uid() then
    raise exception 'Caller is not the seller of this order.' using errhint = 'Only the order seller can mark it shipped.';
  end if;
  update public.orders set status = 'shipped' where id = p_order_id;
  return 'shipped';
end;
$$;

create or replace function public.release_funds(p_order_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_order public.orders%rowtype;
begin
  select * into v_order from public.orders where id = p_order_id;
  if not found then
    raise exception 'Order with id % not found.', p_order_id using errhint = 'Order does not exist.';
  end if;
  if v_order.status != 'shipped' then
    raise exception 'Order is not in shipped status. Current status: %.', v_order.status using errhint = 'Only orders in shipped status can be released.';
