-- Helper function to check if user is assigned to a project/language
create or replace function public.is_assigned_to_project_lang(project_id bigint, user_id uuid, lang text)
returns boolean language sql security invoker as $$
  select exists (
    select 1 from public.translators
    where project_id = is_assigned_to_project_lang.project_id
      and user_id = is_assigned_to_project_lang.user_id
      and lang = is_assigned_to_project_lang.lang
  );
$$ language sql;

-- Helper function to check if user is a reviewer of a language
create or replace function public.is_reviewer_of_lang(project_id bigint, user_id uuid, lang text)
returns boolean language sql security invoker as $$
  select exists (
    select 1 from public.translators
    where project_id = public.is_reviewer_of_lang.project_id
      and user_id = public.is_reviewer_of_lang.user_id
      and lang = public.is_reviewer_of_lang.lang
      and role = 'reviewer'
  );
$$ language sql;

-- Projects RLS: users can see projects they are assigned to
create policy "Users can see assigned projects" on public.projects
  for select using (exists (
    select 1 from public.translators
    where project_id = public.id
      and user_id = auth.uid()
  ));

-- Translators RLS: users can see their assignment rows
create policy "Users can see own translator assignments" on public.translators
  for select using (user_id = auth.uid());

-- Segments RLS
-- R1: Users can see segments of languages they are assigned to
create policy "Users can see assigned segments" on public.segments
  for select using (is_assigned_to_project_lang(project_id, auth.uid(), lang));

-- R2: Translators can edit draft segments in their language, recording themselves
create policy "Translators can update draft segments" on public.segments
  for update using (
    status = 'draft' 
    and is_assigned_to_project_lang(project_id, auth.uid(), lang)
  )
  with check (
    -- Always record translated_by as the current user
    (target_text is distinct from old.target_text or translated_by is distinct from auth.uid())
    and translated_by = auth.uid()
    and status = 'draft'
  );

-- R3: Reviewers can mark draft segments reviewed (and may correct translation)
create policy "Reviewers can mark segments reviewed" on public.segments
  for update using (
    status = 'draft'
    and is_reviewer_of_lang(project_id, auth.uid(), lang)
  )
  with check (
    status = 'reviewed'
    and (target_text is distinct from old.target_text or true) -- allow correction
  );

-- R4: Reviewed segments are locked; no changes to source text, never create/delete
-- Prevent updates on reviewed segments except by service role (handled by with check)
create policy "Reviewed segments are read-only for app users" on public.segments
  for update using (
    status = 'reviewed'
    and auth.role() = 'service_role' -- only service role can change reviewed segments
  )
  with check (
    status = 'reviewed'
    and auth.role() = 'service_role'
  );

-- R5: Anonymous visitors cannot see or change anything is implicitly handled
-- because auth.uid() is null for anon, and policies use auth.uid() which returns null,
-- and null comparisons in USING/CHECK fail unless explicitly handled.
-- The above policies naturally exclude anon because auth.uid() is null.

-- R6: Server-side code using service role keeps full access
-- service_role bypasses RLS by default; no additional policy needed.
