  if new.released_at is not null and new.released_at <= now() then
    -- Once released, prevent any further updates
    if tg_op = 'UPDATE' then
      raise exception 'Cannot update a released lab result';
    end if;
  end if;
  -- Allow editing results that are not yet released
  return new;
end;
