  or exists (select 1 from public.envelopes where id = envelope_id and sender_id = auth.uid())
);

create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security_invoker = true
as $$
declare
  v_status text;
  v_sender_id uuid;
  v_caller_id uuid := auth.uid();
  v_caller_order integer;
  v_total integer;
  v_signed integer;
begin
  select status, sender_id into v_status, v_sender_id
  from public.envelopes
  where id = p_envelope_id;

  if not found or v_status != 'sent' then
    raise exception 'Envelope is not in "sent" status';
  end if;

  if not exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_caller_id) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  if exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = v_caller_id and signed_at is not null) then
    raise exception 'Caller has already signed this envelope';
  end if;

  select sign_order into v_caller_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = v_caller_id;

  if v_caller_order is null then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  if exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id
      and sign_order < v_caller_order
      and signed_at is null
  ) then
    raise exception 'An earlier recipient in sign_order has not yet signed';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = v_caller_id;

  select count(*) into v_total
  from public.envelope_recipients
  where envelope_id = p_envelope_id;

  select count(*) into v_signed
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  if v_signed >= v_total then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
  end if;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security_invoker = true
as $$
declare
  v_status text;
  v_sender_id uuid;
  v_caller_id uuid := auth.uid();
begin
  select status, sender_id into v_status, v_sender_id
  from public.envelopes
  where id = p_envelope_id;

  if not found then
    raise exception 'Envelope not found';
  end if;

  if v_status != 'sent' then
    raise exception 'Envelope is not in "sent" status';
  end if;

  if v_sender_id != v_caller_id then
    raise exception 'Only the sender can void this envelope';
  end if;

  update public.envelopes set status = 'voided' where id = p_envelope_id;

  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;

grant execute on function public.sign_envelope to authenticated;
grant execute on function public.void_envelope to authenticated;
