  using ( auth.role() != 'anon' and ( exists (select 1 from public.envelopes where id = envelope_id and sender_id = auth.uid()) or exists (select 1 from public.envelope_recipients er2 where er2.envelope_id = envelope_recipients.envelope_id and er2.user_id = auth.uid()) ) );

create or replace function public.sign_envelope(p_envelope_id bigint)
  returns text
  language plpgsql
  security definer
as $$
declare
  v_recipient_count bigint;
  v_signed_count bigint;
  v_signer_order integer;
begin
  if auth.role() = 'anon' then
    raise exception 'Anonymous access not allowed';
  end if;

  if not exists (select 1 from public.envelopes where id = p_envelope_id and status = 'sent') then
    raise exception 'Envelope is not sent or not found';
  end if;

  if not exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid()) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  if exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid() and signed_at is not null) then
    raise exception 'Caller has already signed this envelope';
  end if;

  select sign_order into v_signer_order
  from public.envelope_recipients
  where envelope_id = p_envelope_id and user_id = auth.uid();

  if exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and sign_order < v_signer_order and signed_at is null) then
    raise exception 'An earlier recipient in sign_order has not signed yet';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = auth.uid();

  select count(*) into v_recipient_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id;

  select count(*) into v_signed_count
  from public.envelope_recipients
  where envelope_id = p_envelope_id and signed_at is not null;

  if v_signed_count = v_recipient_count then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
    return 'completed';
  else
    return 'sent';
  end if;
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
  returns text
  language plpgsql
  security definer
as $$
begin
  if auth.role() = 'anon' then
    raise exception 'Anonymous access not allowed';
  end if;

  if not exists (select 1 from public.envelopes where id = p_envelope_id and status = 'sent') then
    raise exception 'Envelope is not in sent status';
  end if;

  if auth.uid() != (select sender_id from public.envelopes where id = p_envelope_id) then
    raise exception 'Only the sender can void this envelope';
  end if;

  update public.envelopes set status = 'voided' where id = p_envelope_id;

  return 'voided';
end;
$$;

grant all on public.envelopes to service_role;
grant all on public.envelope_recipients to service_role;
