alter table public.envelopes enable row level security;
alter table public.envelope_recipients enable row level security;

create policy "envelopes_sender_recipient_select" on public.envelopes
  for select using (
    auth.role() = 'service_role' 
    or sender_id = auth.uid() 
    or exists (select 1 from public.envelope_recipients er where er.envelope_id = envelopes.id and er.user_id = auth.uid())
  );

create policy "envelope_recipients_recipient_list_select" on public.envelope_recipients
  for select using (
    auth.role() = 'service_role' 
    or exists (select 1 from public.envelopes e where e.id = envelope_id and (e.sender_id = auth.uid() or exists (select 1 from public.envelope_recipients er where er.envelope_id = e.id and er.user_id = auth.uid())))
  );

create or replace function public.sign_envelope(p_envelope_id bigint)
  returns text
  language plpgsql
  security definer
as
$$
declare
  v_status text;
  v_signer_count integer;
  v_total_recipients integer;
  v_caller_sign_order integer;
begin
  -- Verify envelope exists and is in 'sent' status
  if not exists (select 1 from public.envelopes where id = p_envelope_id and status = 'sent') then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Verify caller is a recipient of this envelope
  if not exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid()) then
    raise exception 'You are not a recipient of this envelope';
  end if;

  -- Verify caller has not already signed
  if exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid() and signed_at is not null) then
    raise exception 'You have already signed this envelope';
  end if;

  -- Retrieve the caller's sign order
  select sign_order into v_caller_sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid();

  -- Verify all recipients with earlier sign order have signed
  if exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and sign_order < v_caller_sign_order and signed_at is null) then
    raise exception 'An earlier recipient has not signed yet';
  end if;

  -- Record the signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id and user_id = auth.uid();

  -- Check if all recipients have signed to mark envelope as completed
  select count(*) into v_total_recipients from public.envelope_recipients where envelope_id = p_envelope_id;
  select count(*) filter (where signed_at is not null) into v_signer_count from public.envelope_recipients where envelope_id = p_envelope_id;

  if v_signer_count = v_total_recipients then
    update public.envelopes set status = 'completed' where id = p_envelope_id and status = 'sent';
  end if;

  -- Return the envelope's current status
  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
  returns text
  language plpgsql
  security definer
as
$$
begin
  -- Verify caller is the sender and envelope is in 'sent' status
  if not exists (select 1 from public.envelopes where id = p_envelope_id and sender_id = auth.uid() and status = 'sent') then
    raise exception 'Only the sender can void this envelope and it must be in sent status';
  end if;

  -- Void the envelope
  update public.envelopes set status = 'voided' where id = p_envelope_id and status = 'sent';

  -- Return the envelope's current status
  return (select status from public.envelopes where id = p_envelope_id);
end;
$$;
