create policy "R3_ModeratorsPinNotes" on public.board_notes for update using (
  auth.role() = 'moderator' -- service role bypasses RLS, so this runs in moderator context
) with check (
  auth.role() = 'moderator' and
  -- Only toggle is_pinned; body/color updates still subject to author checks if needed
  true
);

-- Prevent users from ever setting is_pinned via update (enforce at row level)
-- This trigger ensures is_pinned cannot be changed to true by anyone except moderators
create or replace function public.prevent_user_pin_change()
returns trigger as $$
begin
  -- If the operation is an update and the user is not a moderator/service_role,
  -- force is_pinned back to its original value
  if (TG_OP = 'UPDATE') then
    if (current_setting('role') != 'service_role' and auth.role() != 'moderator') then
      -- Preserve existing is_pinned; effectively blocks setting it to true
      new.is_pinned := old.is_pinned;
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger prevent_user_pin_trigger
  before update on public.board_notes
  for each row
  execute function public.prevent_user_pin_change();

-- Grant anon and authenticated roles read access (R1, R2)
grant select on public.board_notes to anon, authenticated;

-- Grant authenticated role insert/update/delete on their own notes (R2)
-- (RLS policies handle the per-row checks; grant is needed for the operations to be attempted)
grant insert, update, delete on public.board_notes to authenticated;

-- Service role keeps full access (R5) - inherently bypasses RLS, no explicit grant needed
