-- Enable Row Level Security on all relevant tables
alter table public.desks enable row level security;
alter table public.memberships enable row level security;
alter table public.bookings enable row level security;

-- Desks: signed-in users can see every desk
create policy "desks_select_authenticated" on public.desks
using (auth.role() = 'authenticated');

-- Memberships: members can see their own membership
create policy "memberships_select_own" on public.memberships
using (auth.uid() = user_id);

-- Bookings: signed-in users can see every booking (to check availability)
create policy "bookings_select_all_authenticated" on public.bookings
using (auth.role() = 'authenticated');

-- Bookings: insert must be by the user themselves, for today or later, membership valid, premium desks only for premium members
create policy "bookings_insert_valid" on public.bookings
with check (
  auth.uid() = user_id
  and day >= current_date
  and exists (
    select 1 from public.memberships m
    where m.user_id = auth.uid()
    and m.valid_until >= day
  )
  and (
    not exists (
      select 1 from public.desks d
      where d.id = desk_id and d.zone = 'premium'
    ) or exists (
      select 1 from public.memberships m
      where m.user_id = auth.uid()
      and m.tier = 'premium'
    )
  )
);

-- Bookings: members can cancel their own upcoming bookings; past bookings cannot be deleted
create policy "bookings_delete_own_upcoming" on public.bookings
using (auth.uid() = user_id and day >= current_date);

-- Bookings: never edited (blocks all updates via the app)
create policy "bookings_update_none" on public.bookings
using (false);

-- Helper function: enforce max 3 upcoming bookings per member (R3)
create or replace function check_max_upcoming_bookings()
returns trigger
language plpgsql
security invoker
as $$
begin
  -- Service role bypasses RLS, retains full access
  if auth.role() = 'service_role' then
    return new;
  end if;

  if (select count(*) from public.bookings where user_id = auth.uid() and day >= current_date) >= 3 then
    raise exception 'A member cannot hold more than 3 upcoming bookings at a time.';
  end if;

  return new;
end;
$$;

-- Trigger to apply the max-bookings check on insert
create trigger trg_max_upcoming_bookings
before insert on public.bookings
for each row
execute function check_max_upcoming_bookings();
```

