alter table public.articles enable row level security;

-- Helper function to check if current user is an editor
create or replace function public.is_editor() returns boolean language sql security invoker as $$
  select exists (
    select 1 from public.editors
    where user_id = auth.uid()
  );
$$;

-- R1: Read access
-- Anonymous and authenticated can read published articles
create policy "Anyone can read published articles" on public.articles
for select using (status = 'published');

-- Writers can read their own articles
create policy "Writers can read own articles" on public.articles
for select using (author_id = auth.uid());

-- Editors can read every article
create policy "Editors can read all articles" on public.articles
for select using (public.is_editor());

-- R2: Writer operations
-- Writers can create drafts as themselves
create policy "Writers can create drafts" on public.articles
for insert with check (status = 'draft' and author_id = auth.uid());

-- Writers can edit their own drafts (status draft or in_review owned by them)
create policy "Writers can edit own drafts" on public.articles
for update using (author_id = auth.uid() and status in ('draft', 'in_review'));

-- Writers cannot submit (update status to in_review) — that is an editor action
-- (No policy needed; submit is restricted by R3 and the status check below)

-- R3: Editor operations
-- Editors can edit articles in review, publish, or send back to draft
create policy "Editors can update articles in review/published/draft" on public.articles
for update using (public.is_editor() and status in ('draft', 'in_review', 'published'));

-- Editors cannot change published articles via update (enforced by check on published_at)
-- Actually we allow editor update but prevent changes to published_at unless publishing;
-- we'll enforce R4 at the trigger level.

-- R4: Once published, no changes; writers can delete only their own drafts
-- Prevent updates on published articles entirely
create policy "Published articles are immutable" on public.articles
for update using (status != 'published');

-- Writers can delete only their own drafts
create policy "Writers can delete own drafts" on public.articles
for delete using (author_id = auth.uid() and status = 'draft');

-- R5: Editor visibility and immutability of editors table
-- Users can see if they themselves are an editor (via is_editor function already granted)
-- Nobody can change editors through the app — table has no policies for insert/update/delete,
--    and we revoke any accidental grants below.

-- R6: Service role retains full access (already granted by default, explicitly confirmed)
grant all on public.articles to service_role;

-- Grants for authenticated users (needed for policies to function)
grant usage on schema public to authenticated;
grant select on public.editors to authenticated; -- so is_editor can check

-- Ensure service_role has full control
grant all on public.articles to service_role;

-- Triggers to enforce R4: prevent updates on published articles at row level
create or replace trigger trg_prevent_published_update
  before update on public.articles
  for each row
  when (status = 'published')
  execute function public.prevent_published_update();

-- Helper trigger function to block updates on published articles
create or replace function public.prevent_published_update() returns trigger as $$
begin
  raise exception 'Cannot update a published article';
end;
$$ language plpgsql security definer;

-- Optional: prevent deletion of non-draft articles (covered by policy, but trigger as safety)
create or replace trigger trg_prevent_delete_non_draft
  before delete on public.articles
  for each row
  when (status != 'draft')
  execute function public.prevent_delete_non_draft();

create or replace function public.prevent_delete_non_draft() returns trigger as $$
begin
  raise exception 'Can only delete draft articles';
end;
$$ language plpgsql security definer;
