-- Users can see whether they themselves are an editor
create or replace function public.is_editor() returns boolean language sql security invoker as $$
  select exists (select 1 from public.editors where user_id = auth.uid());
$$;

-- R6: Service role full access is default when RLS is enabled, no additional grant needed.
-- The service_role bypasses RLS by default in Supabase.
