  for insert to authenticated
  with check (
    user_id = auth.uid()
    and day >= current_date
    and exists (
      select 1 from public.memberships
      where user_id = auth.uid()
      and memberships.valid_until >= day
    )
    and (
      (select zone from public.desks where id = desk_id) != 'premium'
      or (select tier from public.memberships where user_id = auth.uid()) = 'premium'
    )
  );

-- R4 - delete only own upcoming bookings; past bookings protected
create policy "bookings_delete_upcoming" on public.bookings
  for delete to authenticated
  using (user_id = auth.uid() and day >= current_date);

-- R4 - bookings are never edited
create policy "bookings_no_update" on public.bookings
  for update to authenticated
  using (false);

-- R3 - helper function and trigger: at most 3 upcoming bookings
create function public.check_max_upcoming_bookings()
  returns trigger
  language plpgsql
as $$
begin
  if TG_OP = 'INSERT' then
    if (select count(*) from public.bookings
       where user_id = new.user_id
       and day >= current_date) >= 3 then
      raise exception 'A member can hold at most 3 upcoming bookings at a time.';
    end if;
  end if;
  return new;
end;
$$;
