CREATE POLICY "users_see_own_referrals" ON public.referrals FOR SELECT TO authenticated USING (referrer_id = auth.uid() OR referee_id = auth.uid());
CREATE POLICY "users_see_own_credits" ON public.credits FOR SELECT TO authenticated USING (user_id = auth.uid());

CREATE OR REPLACE FUNCTION public.redeem_referral(p_code text)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_code referral_codes%rowtype;
  v_ref_id bigint;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'User not signed in';
  END IF;

  SELECT * INTO v_code FROM referral_codes WHERE code = p_code;
  IF v_code IS NULL THEN
    RAISE EXCEPTION 'Code does not exist';
  END IF;

  IF v_code.user_id = auth.uid() THEN
    RAISE EXCEPTION 'Cannot redeem own referral code';
  END IF;

  IF EXISTS (SELECT 1 FROM referrals WHERE referee_id = auth.uid()) THEN
    RAISE EXCEPTION 'Already redeemed a referral code';
  END IF;

  IF (SELECT count(*) FROM referrals WHERE referrer_id = v_code.user_id) >= 5 THEN
    RAISE EXCEPTION 'Code owner already has 5 referrals';
  END IF;

  INSERT INTO referrals (referrer_id, referee_id) VALUES (v_code.user_id, auth.uid())
  RETURNING id INTO v_ref_id;

  INSERT INTO credits (user_id, amount, reason) VALUES (auth.uid(), 100, 'referral_redeem');
  INSERT INTO credits (user_id, amount, reason) VALUES (v_code.user_id, 100, 'referral_reward');

  RETURN v_ref_id;
END;
$$;

GRANT SELECT ON public.referral_codes TO authenticated;
GRANT SELECT ON public.referrals TO authenticated;
GRANT SELECT ON public.credits TO authenticated;
