declare
  v_owner_id uuid;
  v_ref_count integer;
  v_new_id bigint;
begin
  set local row_security = off;
  if auth.uid() is null then
    raise exception 'User must be signed in to redeem a referral code';
  end if;

  select user_id into v_owner_id from public.referral_codes where code = p_code;
  if v_owner_id is null then
    raise exception 'Referral code does not exist';
