  if v_ref_count >= 5 then
    raise exception 'The code owner already has 5 referrals';
  end if;

  insert into public.referrals (referrer_id, referee_id) values (v_owner_id, auth.uid()) returning id into v_new_id;

  insert into public.credits (user_id, amount, reason) values (auth.uid(), 100, 'referral reward');
  insert into public.credits (user_id, amount, reason) values (v_owner_id, 100, 'referral reward');

  return v_new_id;
