alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

-- R1: Users can see every class
create policy "Classes are viewable by all signed-in users" on public.classes
  for select using (auth.role() = 'authenticated');

-- R1: Members can see their own spots, instructors can see all spots in their classes
create policy "Users can see own spots, instructors see class spots" on public.class_spots
  for select using (
    auth.role() = 'authenticated' and (
      (user_id = auth.uid()) 
      or 
      exists (
        select 1 from public.classes c 
        where c.id = class_spots.class_id 
        and c.instructor_id = auth.uid()
      )
    )
  );

-- R2: Members can join a class as enrolled only if capacity allows, otherwise waitlisted
-- Helper function to check if a class has room for another enrolled member
create or replace function public.class_has_room(class_id_param bigint, user_id_param uuid)
returns boolean language sql strict as $$
  select exists (
    select 1 from public.class_spots
    where class_id = class_id_param
    and status = 'enrolled'
  ) < (
    select capacity from public.classes where id = class_id_param
  );
$$;

create policy "Members can join class with capacity check" on public.class_spots
  for insert with check (
    auth.role() = 'authenticated' 
    and (
      -- Enrolled if class has room, otherwise waitlisted
      (status = 'enrolled' and public.class_has_room(class_id, user_id)) 
      or 
      (status = 'waitlisted' and not public.class_has_room(class_id, user_id))
    )
  );

-- R3: Members can move own waitlisted to enrolled when room, and can leave class
create policy "Members can update own spot status and delete" on public.class_spots
  for update using (
    auth.role() = 'authenticated' and user_id = auth.uid()
  ) with check (
    -- Can only change status to 'enrolled' when there is room, or to 'waitlisted' always allowed
    (status = 'enrolled' and public.class_has_room(class_id, user_id)) 
    or 
    (status = 'waitlisted')
  )
  for delete using (
    auth.role() = 'authenticated' and user_id = auth.uid()
  );

-- R4: Instructors can remove any spot from the classes they teach
create policy "Instructors can remove spots from their classes" on public.class_spots
  for delete using (
    auth.role() = 'authenticated' and exists (
      select 1 from public.classes c 
      where c.id = class_spots.class_id 
      and c.instructor_id = auth.uid()
    )
  );

-- R5: Anonymous visitors cannot see or change anything (enforced by authenticated check above)
-- R6: Server-side code using the service role keeps full access (bypasses RLS automatically)
