-- RLS enforcement: enforce capacity and status rules via trigger
create or replace function enforce_capacity_and_status()
returns trigger as $$
begin
  -- Insert: only enrolled if count < capacity, otherwise waitlisted
  if new.status = 'enrolled' then
    if (select count(*) from public.class_spots where class_id = new.class_id and status = 'enrolled') >= (select capacity from public.classes where id = new.class_id) then
      -- capacity full, force waitlisted; but allow if user already has a spot (handled elsewhere)
      new.status := 'waitlisted';
    end if;
  end if;
  -- Update: only status change waitlisted -> enrolled when room, or delete
  if new.status != old.status then
    if new.status = 'enrolled' then
      if (select count(*) from public.class_spots where class_id = new.class_id and status = 'enrolled') > (select capacity from public.classes where id = new.class_id) then
        signal 'capacity_full';
      end if;
    elsif new.status = 'left' then
      -- delete handled by caller
    else
      signal 'invalid_status_change';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security definer;

create trigger enforce_capacity_and_status_trigger
  after insert or update on public.class_spots
  for each row
  execute function enforce_capacity_and_status();

-- Grant service_role full access (already implicit, but explicit for clarity)
grant all on public.classes to service_role;
grant all on public.class_spots to service_role;
