-- Enable RLS on tables
alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

-- Classes: signed-in users can see every class; anon sees nothing
create policy "Classes are viewable by signed-in users" on public.classes
  for select using (auth.role() = 'authenticated');

-- class_spots: policies

-- Members can see their own spots
create policy "Members see own spots" on public.class_spots
  for select using (auth.uid() = user_id);

-- Instructors can see every spot in classes they teach
create policy "Instructors see spots in their classes" on public.class_spots
  for select using (
    auth.role() = 'authenticated'
    and exists (
      select 1 from public.classes
      where id = class_id
      and instructor_id = auth.uid()
    )
  );

-- Members can insert their own spot (enrolled if room, else waitlisted)
create policy "Members insert own spot" on public.class_spots
  for insert with check (
    auth.uid() = user_id
    and status in ('enrolled', 'waitlisted')
    and (
      -- enrolled if current enrolled count < capacity
      (
        select count(*) from public.class_spots
        where class_id = class_spots.class_id
        and status = 'enrolled'
      ) < (
        select capacity from public.classes
        where id = class_spots.class_id
      )
      or -- waitlisted if full
        status = 'waitlisted'
      -- if already enrolled, reject
      or not exists (
        select 1 from public.class_spots s2
        where s2.class_id = class_spots.class_id
        and s2.user_id = auth.uid()
        and s2.status = 'enrolled'
      )
    )
  );

-- Members can update own waitlisted -> enrolled when room, and delete own spot
create policy "Members update own spot status and delete" on public.class_spots
  for update using (auth.uid() = user_id) with check (
    -- only status change allowed: waitlisted -> enrolled when room exists
    (status = 'enrolled'
     and not exists (
       select 1 from public.class_spots s2
       where s2.class_id = class_spots.class_id
       and s2.status = 'enrolled'
       and s2.user_id != auth.uid()
       -- room: total enrolled (excluding self) < capacity
       and (select count(*) from public.class_spots s3
            where s3.class_id = class_spots.class_id
            and s3.status = 'enrolled'
            and s3.user_id != auth.uid()
       ) < (select capacity from public.classes where id = class_spots.class_id)
    ))
    or (status != 'enrolled' and status != 'waitlisted') -- other changes blocked
  )
  for delete using (auth.uid() = user_id);

-- Instructors can remove any spot from the classes they teach
create policy "Instructors remove any spot" on public.class_spots
  for delete using (
    auth.role() = 'authenticated'
    and exists (
      select 1 from public.classes
      where id = class_spots.class_id
      and instructor_id = auth.uid()
    )
  );

-- Nobody (anon) can change classes; service_role keeps full access via set_config
-- (No explicit grant needed; service_role bypasses RLS by default)
