```sql
-- Enable RLS on all relevant tables
alter table public.warehouses enable row level security;
alter table public.warehouse_staff enable row level security;
alter table public.stock enable row level security;
alter table public.transfers enable row level security;

-- Helper function to check if user is staff of a warehouse
create function public.is_warehouse_staff(warehouse_id bigint)
returns boolean
language plpgsql
security definer
as $$
begin
  return exists (
    select 1 from public.warehouse_staff
    where warehouse_id = is_warehouse_staff.warehouse_id
      and user_id = auth.uid()
  );
end;
$$;

-- R1: Signed-in users can see warehouses
create policy "Staff can see warehouses"
on public.warehouses
for select
to authenticated
using (true);

-- R1: Staff can see stock of their warehouses and transfers involving them
create policy "Staff can see stock"
on public.stock
for select
to authenticated
using (public.is_warehouse_staff(warehouse_id));

create policy "Staff can see transfers"
on public.transfers
for select
to authenticated
using (
  (from_warehouse in (select warehouse_id from public.warehouse_staff where user_id = auth.uid()))
  or
  (to_warehouse in (select warehouse_id from public.warehouse_staff where user_id = auth.uid()))
);

-- R5: Anonymous visitors cannot see anything
create policy "Anonymous cannot see warehouses"
on public.warehouses
for select
to anon
using (false);

create policy "Anonymous cannot see stock"
on public.stock
for select
to anon
using (false);

create policy "Anonymous cannot see transfers"
on public.transfers
for select
to anon
using (false);

-- R2: Nobody can change stock or transfers directly
create policy "Nobody can change stock"
on public.stock
for all
to authenticated
using (false)
with check (false);

create policy "Nobody can change transfers"
on public.transfers
for all
to authenticated
using (false)
with check (false);

-- R6: Service role keeps full access (granted explicitly if needed, but RLS policies above exclude it implicitly via role checks; explicit grant for clarity)
grant all on public.warehouses to service_role;
grant all on public.warehouse_staff to service_role;
grant all on public.stock to service_role;
grant all on public.transfers to service_role;

-- R3, R4: transfer_stock function
-- The function body is assumed to exist; we ensure it respects RLS and permissions.
-- We create or replace the function with a security definer that runs as the caller (auth.uid())
-- and includes the validation logic per the rules.
create or replace function public.transfer_stock(
  p_from bigint,
  p_to bigint,
  p_sku text,
  p_qty integer
)
returns integer
language plpgsql
security invoker  -- runs as the calling user
as $$
declare
  source_qty integer;
  source_stock record;
  dest_stock record;
  left_qty integer;
begin
  -- Rule R4: quantity must be positive
  if p_qty <= 0 then
    raise exception 'Quantity must be positive';
  end if;

  -- Rule R4: source warehouse must exist
  if not exists (select 1 from public.warehouses where id = p_from) then
    raise exception 'Source warehouse does not exist';
  end if;

  -- Rule R4: destination warehouse must exist
  if not exists (select 1 from public.warehouses where id = p_to) then
    raise exception 'Destination warehouse does not exist';
  end if;

  -- Rule R4: source and destination must not be the same
  if p_from = p_to then
    raise exception 'Source and destination must be different';
  end if;

  -- Rule R4: caller must be staff of the source warehouse
  if not public.is_warehouse_staff(p_from) then
    raise exception 'Caller is not staff of the source warehouse';
  end if;

  -- Check source stock quantity
  select qty into source_qty from public.stock where warehouse_id = p_from and sku = p_sku;
  if source_qty is null then
    raise exception 'Source does not have stock of this sku';
  end if;
  if source_qty < p_qty then
    raise exception 'Source does not have enough stock';
  end if;

  -- Update source stock
  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku;

  -- Handle destination stock: create if needed, otherwise increment
  -- Using insert ... on conflict to handle race conditions / creation
  insert into public.stock (warehouse_id, sku, qty)
  values (p_to, p_sku, p_qty)
  on conflict (warehouse_id, sku)
  do update set qty = stock.qty + p_qty;

  -- Record the transfer
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  -- Return quantity left at source
  select qty into left_qty from public.stock where warehouse_id = p_from and sku = p_sku;
  return left_qty;
end;
$$;

-- Grant execute on the function to authenticated users (staff)
grant execute on function public.transfer_stock to authenticated;
```

