-- set_member_role function
create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text language sql security invoker as $$
declare
  v_caller_role text;
  v_target_role text;
begin
  -- caller must be owner or admin of the org
  select om.role into v_caller_role
  from public.org_members om
  where om.org_id = p_org_id and om.user_id = auth.uid();

  if v_caller_role is null or v_caller_role not in ('owner', 'admin') then
    raise exception 'Only org owners and admins can change roles.';
  end if;

  -- cannot target yourself
  if p_user_id = auth.uid() then
    raise exception 'Cannot change your own role.';
  end if;

  -- cannot target an owner
  select om.role into v_target_role
  from public.org_members om
  where om.org_id = p_org_id and om.user_id = p_user_id;

  if v_target_role = 'owner' then
    raise exception 'Cannot change an owner''s role.';
  end if;

  -- target must be a member of the org
  if v_target_role is null then
    raise exception 'Target user is not a member of this organization.';
  end if;

  -- only allow admin or member
  if p_role not in ('admin', 'member') then
    raise exception 'Role must be admin or member.';
  end if;

  -- apply the update
  update public.org_members
  set role = p_role
  where org_id = p_org_id and user_id = p_user_id;

  return p_role;
end;
$$;

