alter table public.org_members enable row level security;
alter table public.leaderboard enable row level security;

-- Helper function to check if current user is an owner or admin of a given org
create function public.is_org_owner_or_admin(p_org_id bigint) returns boolean language sql strict as $$
  select case when auth.role() = 'service_role' then true
              else exists (
                select 1 from public.org_members
                where org_id = p_org_id
                  and user_id = auth.uid()
                  and role in ('owner', 'admin')
              ) end;
$$;

-- RLS policies for org_members (R1, R3, R5, R6)
create policy "org_members_select_anon_deny" on public.org_members
  for select to anon using (false);

create policy "org_members_select_auth" on public.org_members
  for select to authenticated using (true);

create policy "org_members_insert_owner" on public.org_members
  for insert to authenticated with check (
    auth.role() = 'service_role' or
    (auth.role() = 'authenticated' and exists (
      select 1 from public.org_members
      where org_id = coalesce(current_setting('app.org_id')::bigint, -1)
        and user_id = auth.uid()
        and role = 'owner'
    ))
  );

create policy "org_members_update_role" on public.org_members
  for update using (auth.role() = 'service_role' or public.is_org_owner_or_admin(org_id))
  with check (auth.role() = 'service_role' or public.is_org_owner_or_admin(org_id));

-- RLS policies for leaderboard (R1, R5)
create policy "leaderboard_select_anon_deny" on public.leaderboard
  for select to anon using (false);

create policy "leaderboard_select_auth" on public.leaderboard
  for select to authenticated using (true);

-- RLS policies for set_member_role function (R3, R4, R6)
-- The function itself enforces checks; no policy needed on the function object,
-- but we ensure service_role bypass. The function body already uses auth.role().

-- RLS policies for recalculate_leaderboard function (R4)
-- Restrict execution to service_role only via a policy on the function
create policy "recalculate_leaderboard_service_only" on public.recalculate_leaderboard
  for execute to anon using (false)
  using (auth.role() = 'service_role');

-- Grants for anon (R5): none needed beyond deny policies
-- Grants for authenticated (R1): select on leaderboard, select on org_members
grant select on public.leaderboard to authenticated;
grant select on public.org_members to authenticated;

-- Grants for service_role (R6): full access
grant all on public.org_members to service_role;
grant all on public.leaderboard to service_role;
grant execute on public.set_member_role to service_role;
grant execute on public.recalculate_leaderboard to service_role;
