create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text language sql security invoker as $$
begin
  -- Must be owner or admin of the org
  if not exists (
    select 1 from public.org_members
    where org_id = p_org_id
    and user_id = auth.uid()
    and role in ('owner', 'admin')
  ) then
    raise exception 'Only org owners or admins can change roles';
  end if;

  -- Cannot target yourself
  if p_user_id = auth.uid() then
    raise exception 'You cannot change your own role';
  end if;

  -- Cannot target an owner
  if exists (
    select 1 from public.org_members
    where org_id = p_org_id
    and user_id = p_user_id
    and role = 'owner'
  ) then
    raise exception 'Cannot change an owner''s role';
  end if;

  -- Target must be a member of the org
  if not exists (
    select 1 from public.org_members
    where org_id = p_org_id
    and user_id = p_user_id
  ) then
    raise exception 'User is not a member of this organization';
  end if;

  -- Only allow admin or member role changes
  if p_role not in ('admin', 'member') then
    raise exception 'Role must be admin or member';
  end if;

  -- Apply the role change
  update public.org_members
  set role = p_role
  where org_id = p_org_id
  and user_id = p_user_id;

  return p_role;
end;
$$;

