-- Function: set_member_role (owner/admin can change roles)
create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text
language plpgsql
security definer
as $$
declare
  v_caller_role text;
  v_target_role text;
begin
  -- Anonymous / no auth cannot call
  if auth.role() != 'authenticated' then
    raise exception 'Anonymous users cannot change memberships.';
  end if;

  -- Cannot target yourself
  if p_user_id = auth.uid() then
    raise exception 'You cannot change your own role.';
  end if;

  -- Target must be a member of the organization
  select role into v_target_role from public.org_members where org_id = p_org_id and user_id = p_user_id;
  if v_target_role is null then
    raise exception 'Target user is not a member of this organization.';
  end if;

  -- Caller must be owner or admin of the org
  if not public.is_org_owner_or_admin(p_org_id, auth.uid()) then
    raise exception 'Only owners and admins can change membership roles.';
  end if;

  -- Validate target role
  if p_role not in ('admin', 'member') then
    raise exception 'Role must be admin or member.';
  end if;

  -- Cannot downgrade an owner to member (if caller is owner, target cannot be owner)
  if p_role = 'member' and v_target_role = 'owner' then
    raise exception 'Cannot downgrade an owner to member.';
  end if;

  -- Perform the update
  update public.org_members set role = p_role where org_id = p_org_id and user_id = p_user_id;
  return p_role;
end;
$$;

